  // Load business settings logo
  useEffect(() => {
    const loadLogo = async () => {
      try {
        const cached = getCachedSettings();
        if (cached?.logo?.url) {
          setLogoUrl(cached.logo.url);
        } else {
          const settings = await loadBusinessSettings();
          if (settings?.logo?.url) setLogoUrl(settings.logo.url);
