export default function LocationSelectorOverlay({ isOpen, onClose }) {
  const s = useStyles()
  const t = useTheme()
  const insets = useSafeAreaInsets()
  const { height: windowHeight } = useWindowDimensions()
  const { location, loading, requestLocation } = useGeoLocation()
