      }

      // Check if API call was successful
      if (res.data.success === false) {
        throw new Error(res.data.message || "OLA Maps API returned error")
      }

      // Backend returns: { success: true, data: { results: [{ formatted_address, address_components: { city, state, country, area } }] } }
      const backendData = res?.data?.data || {}

      // Debug: Check backend data structure
      debugLog("?? Backend data structure:", {
        hasResults: !!backendData.results,
        hasResult: !!backendData.result,
        keys: Object.keys(backendData),
        dataType: typeof backendData,
        backendData: JSON.stringify(backendData, null, 2).substring(0, 500) // First 500 chars
      })

      // Handle different OLA Maps response structures
      // Backend processes OLA Maps response and returns: { results: [{ formatted_address, address_components: { city, state, area } }] }
      let result = null;
      if (backendData.results && Array.isArray(backendData.results) && backendData.results.length > 0) {
        result = backendData.results[0];
        debugLog("? Using results[0] from backend")
      } else if (backendData.result && Array.isArray(backendData.result) && backendData.result.length > 0) {
        result = backendData.result[0];
        debugLog("? Using result[0] from backend")
      } else if (backendData.results && !Array.isArray(backendData.results)) {
        result = backendData.results;
        debugLog("? Using results object from backend")
      } else {
        result = backendData;
        debugLog("?? Using backendData directly (fallback)")
      }

      if (!result) {
        debugWarn("?? No result found in backend data")
        result = {};
      }

      debugLog("?? Parsed result:", {
        hasFormattedAddress: !!result.formatted_address,
        hasAddressComponents: !!result.address_components,
        formattedAddress: result.formatted_address,
        addressComponents: result.address_components
      })

      // Extract address_components - handle both object and array formats
      let addressComponents = {};
      if (result.address_components) {
        if (Array.isArray(result.address_components)) {
          // Google Maps style array
          result.address_components.forEach(comp => {
            const types = comp.types || [];
            if (types.includes('sublocality') || types.includes('sublocality_level_1')) {
              addressComponents.area = comp.long_name || comp.short_name;
            } else if (types.includes('neighborhood') && !addressComponents.area) {
              addressComponents.area = comp.long_name || comp.short_name;
            } else if (types.includes('locality')) {
              addressComponents.city = comp.long_name || comp.short_name;
            } else if (types.includes('administrative_area_level_1')) {
              addressComponents.state = comp.long_name || comp.short_name;
            } else if (types.includes('country')) {
              addressComponents.country = comp.long_name || comp.short_name;
            }
          });
        } else {
          // Object format
          addressComponents = result.address_components;
        }
      } else if (result.components) {
        addressComponents = result.components;
      }

      debugLog("?? Parsed result structure:", {
        result,
        addressComponents,
        hasArrayComponents: Array.isArray(result.address_components),
        hasObjectComponents: !Array.isArray(result.address_components) && !!result.address_components
      })

      // Extract address details - try multiple possible response structures
      let city = addressComponents?.city ||
        result?.city ||
        result?.locality ||
        result?.address_components?.city ||
        ""

      let state = addressComponents?.state ||
        result?.state ||
        result?.administrative_area_level_1 ||
        result?.address_components?.state ||
        ""

      let country = addressComponents?.country ||
        result?.country ||
        result?.country_name ||
        result?.address_components?.country ||
        ""

      let formattedAddress = result?.formatted_address ||
        result?.formattedAddress ||
        result?.address ||
        ""

      // PRIORITY 1: Extract area from formatted_address FIRST (most reliable for Indian addresses)
      // Indian address format: "Area, City, State" e.g., "New Palasia, Indore, Madhya Pradesh"
      // ALWAYS try formatted_address FIRST - it's the most reliable source and preserves full names like "New Palasia"
      let area = ""
      if (formattedAddress) {
        const addressParts = formattedAddress.split(',').map(part => part.trim()).filter(part => part.length > 0)

        debugLog("?? Parsing formatted address for area:", { formattedAddress, addressParts, city, state, currentArea: area })

        // HELLO PARTH-STYLE: If we have 3+ parts, first part is ALWAYS the area/locality
        // Format: "New Palasia, Indore, Madhya Pradesh" -> area = "New Palasia"
        if (addressParts.length >= 3) {
          const firstPart = addressParts[0]
          const secondPart = addressParts[1] // Usually city
          const thirdPart = addressParts[2]  // Usually state

          // First part is the area (e.g., "New Palasia")
          // Second part is usually city (e.g., "Indore")
          // Third part is usually state (e.g., "Madhya Pradesh")
          if (firstPart && firstPart.length > 2 && firstPart.length < 50) {
            // Make sure first part is not the same as city or state
            const firstLower = firstPart.toLowerCase()
            const cityLower = (city || secondPart || "").toLowerCase()
            const stateLower = (state || thirdPart || "").toLowerCase()

            if (firstLower !== cityLower &&
              firstLower !== stateLower &&
              !firstPart.match(/^\d+/) && // Not a number
              !firstPart.match(/^\d+\s*(km|m|meters?)$/i) && // Not a distance
              !firstLower.includes("district") && // Not a district name
              !firstLower.includes("city")) { // Not a city name
              area = firstPart
              debugLog("??? EXTRACTED AREA from formatted address (3+ parts):", area)

              // Also update city if second part matches better
              if (secondPart && (!city || secondPart.toLowerCase() !== city.toLowerCase())) {
                city = secondPart
              }
              // Also update state if third part matches better
              if (thirdPart && (!state || thirdPart.toLowerCase() !== state.toLowerCase())) {
                state = thirdPart
              }
            }
          }
        } else if (addressParts.length === 2 && !area) {
          // Two parts: Could be "Area, City" or "City, State"
          const firstPart = addressParts[0]
          const secondPart = addressParts[1]

          // Check if first part is city (if we already have city name)
          const isFirstCity = city && firstPart.toLowerCase() === city.toLowerCase()

          // If first part is NOT the city, it's likely the area
          if (!isFirstCity &&
            firstPart.length > 2 &&
            firstPart.length < 50 &&
            !firstPart.toLowerCase().includes("district") &&
            !firstPart.toLowerCase().includes("city") &&
            !firstPart.match(/^\d+/)) {
            area = firstPart
            debugLog("? Extracted area from 2 part address:", area)
            // Update city if second part exists
            if (secondPart && !city) {
              city = secondPart
            }
          } else if (isFirstCity) {
            // First part is city, second part might be state
            // No area in this case, but update state if needed
            if (secondPart && !state) {
              state = secondPart
            }
          }
        } else if (addressParts.length === 1 && !area) {
          // Single part - could be just city or area
          const singlePart = addressParts[0]
          if (singlePart && singlePart.length > 2 && singlePart.length < 50) {
            // If it doesn't match city exactly, it might be an area
            if (!city || singlePart.toLowerCase() !== city.toLowerCase()) {
              // Don't use as area if it looks like a city name (contains common city indicators)
              if (!singlePart.toLowerCase().includes("city") &&
                !singlePart.toLowerCase().includes("district")) {
                // Could be area, but be cautious - only use if we're sure
                debugLog("?? Single part address - ambiguous, not using as area:", singlePart)
              }
            }
          }
        }
      }

      // PRIORITY 2: If still no area from formatted_address, try from address_components (fallback)
      // Note: address_components might have incomplete/truncated names like "Palacia" instead of "New Palasia"
      // So we ALWAYS prefer formatted_address extraction over address_components
      if (!area && addressComponents) {
        // Try all possible area fields (but exclude state and generic names!)
        const possibleAreaFields = [
          addressComponents.sublocality,
          addressComponents.sublocality_level_1,
          addressComponents.neighborhood,
          addressComponents.sublocality_level_2,
          addressComponents.locality,
          addressComponents.area, // Check area last
        ].filter(field => {
          // Filter out invalid/generic area names
          if (!field) return false
          const fieldLower = field.toLowerCase()
          return fieldLower !== state.toLowerCase() &&
            fieldLower !== city.toLowerCase() &&
            !fieldLower.includes("district") &&
            !fieldLower.includes("city") &&
            field.length > 3 // Minimum length
        })

        if (possibleAreaFields.length > 0) {
          const fallbackArea = possibleAreaFields[0]
          // CRITICAL: If formatted_address exists and has a different area, prefer formatted_address
          // This ensures "New Palasia" from formatted_address beats "Palacia" from address_components
          if (formattedAddress && formattedAddress.toLowerCase().includes(fallbackArea.toLowerCase())) {
            // formatted_address contains the fallback area, so it's likely more complete
            // Try one more time to extract from formatted_address
            debugLog("?? address_components has area but formatted_address might have full name, re-checking formatted_address")
          } else {
            area = fallbackArea
            debugLog("? Extracted area from address_components (fallback):", area)
          }
        }
      }

      // Also check address_components array structure (Google Maps style)
      if (!area && result?.address_components && Array.isArray(result.address_components)) {
        const components = result.address_components
        // Find sublocality or neighborhood in the components array
        const sublocality = components.find(comp =>
          comp.types?.includes('sublocality') ||
          comp.types?.includes('sublocality_level_1') ||
          comp.types?.includes('neighborhood')
        )
        if (sublocality?.long_name || sublocality?.short_name) {
          area = sublocality.long_name || sublocality.short_name
        }
      }

      // FINAL FALLBACK: If area is still empty, force extract from formatted_address
      // This is the last resort - be very aggressive (HELLO PARTH-STYLE)
      // Even if formatted_address only has 2 parts (City, State), try to extract area
      if (!area && formattedAddress) {
        const parts = formattedAddress.split(',').map(p => p.trim()).filter(p => p.length > 0)
        debugLog("?? Final fallback: Parsing formatted_address for area", { parts, city, state })

        if (parts.length >= 2) {
          const potentialArea = parts[0]
          // Very lenient check - if it's not obviously city/state, use it as area
          const potentialAreaLower = potentialArea.toLowerCase()
          const cityLower = (city || "").toLowerCase()
          const stateLower = (state || "").toLowerCase()

          if (potentialArea &&
            potentialArea.length > 2 &&
            potentialArea.length < 50 &&
            !potentialArea.match(/^\d+/) &&
            potentialAreaLower !== cityLower &&
            potentialAreaLower !== stateLower &&
            !potentialAreaLower.includes("district") &&
            !potentialAreaLower.includes("city")) {
            area = potentialArea
            debugLog("??? FORCE EXTRACTED area (final fallback):", area)
          }
        }
      }

      // Final validation and logging
      debugLog("??? FINAL PARSED OLA Maps response:", {
        city,
        state,
        country,
        area,
        formattedAddress,
        hasArea: !!area,
        areaLength: area?.length || 0
      })

      // CRITICAL: If formattedAddress has only 2 parts, OLA Maps didn't provide sublocality
      // Try to get more detailed location using coordinates-based search
      if (!area && formattedAddress) {
        const parts = formattedAddress.split(',').map(p => p.trim()).filter(p => p.length > 0)

        // If we have 3+ parts, extract area from first part
        if (parts.length >= 3) {
          // HELLO PARTH PATTERN: "New Palasia, Indore, Madhya Pradesh"
          // First part = Area, Second = City, Third = State
          const potentialArea = parts[0]
          // Validate it's not state, city, or generic names
          const potentialAreaLower = potentialArea.toLowerCase()
          if (potentialAreaLower !== state.toLowerCase() &&
            potentialAreaLower !== city.toLowerCase() &&
            !potentialAreaLower.includes("district") &&
            !potentialAreaLower.includes("city")) {
            area = potentialArea
            if (!city && parts[1]) city = parts[1]
            if (!state && parts[2]) state = parts[2]
            debugLog("??? HELLO PARTH-STYLE EXTRACTION:", { area, city, state })
          }
        } else if (parts.length === 2) {
          // Only 2 parts: "Indore, Madhya Pradesh" - area is missing
          // OLA Maps API didn't provide sublocality
          debugWarn("?? Only 2 parts in address - OLA Maps didn't provide sublocality")
          // Try to extract from other fields in the response
          // Check if result has any other location fields
          if (result.locality && result.locality !== city) {
            area = result.locality
            debugLog("? Using locality as area:", area)
          } else if (result.neighborhood) {
            area = result.neighborhood
            debugLog("? Using neighborhood as area:", area)
          } else {
            // Leave area empty - will show city instead
            area = ""
          }
        }
      }

      // FINAL VALIDATION: Never use state as area!
      if (area && state && area.toLowerCase() === state.toLowerCase()) {
        debugWarn("?????? REJECTING area (same as state):", area)
        area = ""
      }

      // FINAL VALIDATION: Reject district names
      if (area && area.toLowerCase().includes("district")) {
        debugWarn("?????? REJECTING area (contains district):", area)
        area = ""
      }

      // If we have a valid formatted address or city, return it
      if (formattedAddress || city) {
        const finalLocation = {
          city: city || "Unknown City",
          state: state || "",
          country: country || "",
          area: area || "", // Area is CRITICAL - must be extracted
          address: formattedAddress || `${city || "Current Location"}`,
          formattedAddress: formattedAddress || `${city || "Current Location"}`,
        }

        debugLog("??? RETURNING LOCATION DATA:", finalLocation)
        return finalLocation
      }

      // If no valid data, throw to trigger fallback
      throw new Error("No valid address data from OLA Maps")
    } catch (err) {
      debugWarn("?? OLA Maps geocoding failed, trying BigDataCloud:", err.message)
      // Fallback to direct reverse geocoding (BigDataCloud)
      try {
        return await reverseGeocodeWithGoogleMaps(latitude, longitude)
      } catch (fallbackErr) {
        // If all fail, return minimal location data
        debugError("? All reverse geocoding failed:", fallbackErr)
        return {
          city: "Current Location",
          address: `${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,
          formattedAddress: `${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,
        }
      }
    }
  }

  /* ===================== DB FETCH ===================== */
  const fetchLocationFromDB = async () => {
    try {
      // Check if user is authenticated before trying to fetch from DB
      const userToken = localStorage.getItem('user_accessToken') || localStorage.getItem('accessToken')
      if (!userToken || userToken === 'null' || userToken === 'undefined') {
        // User not logged in - skip DB fetch, return null to use localStorage
        return null
      }

      const dbLocationAgeMs = Date.now() - lastDbLocationFetchAtRef.current
      if (lastDbLocationRef.current && dbLocationAgeMs < DB_LOCATION_FETCH_TTL_MS) {
        return lastDbLocationRef.current
      }

      // eslint-disable-next-line no-undef -- undefined on the web too (kept: same behaviour, the call throws into its catch)
      const res = await userAPI.getLocation()
      const loc = res?.data?.data?.location
      if (loc?.latitude && loc?.longitude) {
        // Validate coordinates are in India range BEFORE attempting geocoding
        const isInIndiaRange = loc.latitude >= 6.5 && loc.latitude <= 37.1 && loc.longitude >= 68.7 && loc.longitude <= 97.4 && loc.longitude > 0

        if (!isInIndiaRange || loc.longitude < 0) {
          // Coordinates are outside India - return placeholder
          debugWarn("?? Coordinates from DB are outside India range:", { latitude: loc.latitude, longitude: loc.longitude })
          const outOfRangeLocation = {
            latitude: loc.latitude,
            longitude: loc.longitude,
            city: "Current Location",
            state: "",
            country: "",
            area: "",
            address: "Select location",
            formattedAddress: "Select location",
          }
          lastDbLocationRef.current = outOfRangeLocation
          lastDbLocationFetchAtRef.current = Date.now()
          return outOfRangeLocation
        }

        const hasUsableStoredAddress =
          (loc.formattedAddress && loc.formattedAddress !== "Select location") ||
          (loc.address && loc.address !== "Select location") ||
          (loc.city && loc.city !== "Current Location")

        if (hasUsableStoredAddress) {
          const storedLocation = {
            latitude: loc.latitude,
            longitude: loc.longitude,
            city: loc.city || "Current Location",
            area: loc.area || "",
            state: loc.state || "",
            country: loc.country || "",
            address: loc.address || loc.formattedAddress || "Select location",
            formattedAddress: loc.formattedAddress || loc.address || "Select location"
          }
          lastDbLocationRef.current = storedLocation
          lastDbLocationFetchAtRef.current = Date.now()
          return storedLocation
        }

        try {
          const addr = await reverseGeocodeWithGoogleMaps(
            loc.latitude,
            loc.longitude,
            { includePlaceDetails: false }
          )
          const resolvedLocation = { ...addr, latitude: loc.latitude, longitude: loc.longitude }
          lastDbLocationRef.current = resolvedLocation
          lastDbLocationFetchAtRef.current = Date.now()
          return resolvedLocation
        } catch (geocodeErr) {
          // If reverse geocoding fails, return location without coordinates in address
          debugWarn("?? Reverse geocoding failed in fetchLocationFromDB:", geocodeErr.message)
          const fallbackLocation = {
            latitude: loc.latitude,
            longitude: loc.longitude,
            city: "Current Location",
            area: "",
            state: "",
            address: "Select location", // Don't show coordinates
            formattedAddress: "Select location", // Don't show coordinates
          }
          lastDbLocationRef.current = fallbackLocation
          lastDbLocationFetchAtRef.current = Date.now()
          return fallbackLocation
        }
      }
    } catch (err) {
      // Silently fail for 404/401 (user not authenticated) or network errors
      if (err.code !== "ERR_NETWORK" && err.response?.status !== 404 && err.response?.status !== 401) {
        debugError("DB location fetch error:", err)
      }
    }
    return null
  }

  /* ===================== MAIN LOCATION ===================== */
  const getLocation = async (updateDB = true, forceFresh = false, showLoading = false) => {
    // If not forcing fresh, try DB first (faster)
    let dbLocation = !forceFresh ? await fetchLocationFromDB() : null
    if (dbLocation && !forceFresh) {
      setLocation(dbLocation)
      if (showLoading) setGlobalLocationLoading(false)
      return dbLocation
    }

    if (!navigator.geolocation) {
      setError("Geolocation not supported")
      if (showLoading) setGlobalLocationLoading(false)
      return dbLocation
    }

    // Helper function to get position with retry mechanism
    const getPositionWithRetry = (options, retryCount = 0) => {
      return new Promise((resolve, reject) => {
        const isRetry = retryCount > 0
        debugLog(`?? Requesting location${isRetry ? ' (retry with lower accuracy)' : ' (high accuracy)'}...`)
        debugLog(`?? Force fresh: ${forceFresh ? 'YES' : 'NO'}, maximumAge: ${options.maximumAge || (forceFresh ? 0 : 60000)}`)

        // Use cached location if available and not too old (faster response)
        // If forceFresh is true, don't use cache (maximumAge: 0)
        const cachedOptions = {
          ...options,
          maximumAge: forceFresh ? 0 : (options.maximumAge || 60000), // If forceFresh, get fresh location
        }

        getFastAccuratePosition(
          async (pos) => {
            try {
              const { latitude, longitude, accuracy } = pos.coords
              const timestamp = pos.timestamp || Date.now()

              debugLog(`? Got location${isRetry ? ' (lower accuracy)' : ' (high accuracy)'}:`, {
                latitude,
                longitude,
                accuracy: `${accuracy}m`,
                timestamp: new Date(timestamp).toISOString(),
                coordinates: `${latitude.toFixed(8)}, ${longitude.toFixed(8)}`
              })

              // Validate coordinates are in India range BEFORE attempting geocoding
              // India: Latitude 6.5° to 37.1° N, Longitude 68.7° to 97.4° E
              let finalLat = latitude
              let finalLng = longitude
              const isInIndiaRange = latitude >= 6.5 && latitude <= 37.1 && longitude >= 68.7 && longitude <= 97.4 && longitude > 0

              if (!isInIndiaRange || longitude < 0) {
                debugWarn("?? Coordinates outside India range:", { latitude, longitude })
              }

              debugLog("?? Calling reverse geocode with coordinates:", { latitude: finalLat, longitude: finalLng })
              let addr
              try {
                addr = await reverseGeocodeWithGoogleMaps(finalLat, finalLng, {
                  includePlaceDetails: Boolean(forceFresh && showLoading)
                })
                debugLog("? Reverse geocoding successful:", addr)
              } catch (geocodeErr) {
                debugWarn("?? Primary geocoding failed, trying fallback:", geocodeErr.message)
                try {
                  // Fallback to direct reverse geocode (BigDataCloud)
                  addr = await reverseGeocodeDirect(finalLat, finalLng)
                  debugLog("? Fallback geocoding successful:", addr)

                  // Validate fallback result - if it still has placeholder values, don't use it
                  if (addr.city === "Current Location" || addr.address.includes(finalLat.toFixed(4))) {
                    debugWarn("?? Fallback geocoding returned placeholder, will use Vijay Nagar default")
                    addr = {
                      city: "Indore",
                      state: "Madhya Pradesh",
                      country: "India",
                      area: "Vijay Nagar",
                      address: "Vijay Nagar, Indore, Madhya Pradesh",
                      formattedAddress: "Vijay Nagar, Indore, Madhya Pradesh",
                    }
                  }
                } catch (fallbackErr) {
                  debugError("? All geocoding methods failed:", fallbackErr.message)
                  addr = {
                    city: "Indore",
                    state: "Madhya Pradesh",
                    country: "India",
                    area: "Vijay Nagar",
                    address: "Vijay Nagar, Indore, Madhya Pradesh",
                    formattedAddress: "Vijay Nagar, Indore, Madhya Pradesh",
                  }
                }
              }

              // Update coordinates in original variables for consistency
              let finalLocLatitude = finalLat
              let finalLocLongitude = finalLng
              debugLog("Reverse geocode result:", addr)
              if (addr?.formattedAddress && addr.formattedAddress !== "Select location") {
                lastResolvedAddressRef.current = addr
                lastGeocodedCoordsRef.current = { latitude, longitude }
                lastGeocodeAtRef.current = Date.now()
              }
              // Ensure we don't use coordinates as address if we have area/city
              // Keep the complete formattedAddress from geocoder when available
              const completeFormattedAddress = addr.formattedAddress || "";
              let displayAddress = addr.address || "";

              // If address contains coordinates pattern, use area/city instead
              const isCoordinatesPattern = /^-?\d+\.\d+,\s*-?\d+\.\d+$/.test(displayAddress.trim());
              if (isCoordinatesPattern) {
                if (addr.area && addr.area.trim() !== "") {
                  displayAddress = addr.area;
                } else if (addr.city && addr.city.trim() !== "" && addr.city !== "Unknown City") {
                  displayAddress = addr.city;
                }
              }

              // Build location object with ALL fields from reverse geocoding
              const finalLoc = {
                ...addr, // This includes: city, state, area, street, streetNumber, postalCode, formattedAddress
                latitude: finalLocLatitude,
                longitude: finalLocLongitude,
                accuracy: accuracy || null,
                address: displayAddress, // Locality parts for navbar display
                formattedAddress: completeFormattedAddress || addr.formattedAddress || displayAddress // Complete detailed address
              }

              // Check if location has placeholder values - don't save placeholders
              const hasPlaceholder =
                finalLoc.city === "Current Location" ||
                finalLoc.address === "Select location" ||
                finalLoc.formattedAddress === "Select location" ||
                (!finalLoc.city && !finalLoc.address && !finalLoc.formattedAddress && !finalLoc.area);

              if (hasPlaceholder) {
                debugWarn("?? Skipping save - location contains placeholder values:", finalLoc)
                // Don't save placeholder values to localStorage or DB
                // Just set in state for display but don't persist
                const coordOnlyLoc = {
                  latitude,
                  longitude,
                  accuracy: accuracy || null,
                  city: finalLoc.city,
                  address: finalLoc.address,
                  formattedAddress: finalLoc.formattedAddress
                }
                setLocation(coordOnlyLoc)
                setPermissionGranted(true)
                if (showLoading) setGlobalLocationLoading(false)
                setError(null)
                resolve(coordOnlyLoc)
                return
              }

              debugLog("?? Saving location:", finalLoc)
              persistFoodUserLocation(finalLoc)
              setLocation(finalLoc)
              setPermissionGranted(true)
              if (showLoading) setGlobalLocationLoading(false)
              setError(null)

              if (updateDB) {
                await updateLocationInDB(finalLoc).catch(err => {
                  debugWarn("Failed to update location in DB:", err)
                })
              }
              resolve(finalLoc)
            } catch (err) {
              debugError("? Error processing location:", err)
              // Try one more time with direct reverse geocode as last resort
              const { latitude, longitude } = pos.coords

              try {
                debugLog("?? Last attempt: trying direct reverse geocode...")
                const lastResortAddr = await reverseGeocodeDirect(latitude, longitude)

                // Check if we got valid data (not just coordinates)
                if (lastResortAddr &&
                  lastResortAddr.city !== "Current Location" &&
                  !lastResortAddr.address.includes(latitude.toFixed(4)) &&
                  lastResortAddr.formattedAddress &&
                  !lastResortAddr.formattedAddress.includes(latitude.toFixed(4))) {
                  const lastResortLoc = {
                    ...lastResortAddr,
                    latitude,
                    longitude,
                    accuracy: pos.coords.accuracy || null
                  }
                  debugLog("? Last resort geocoding succeeded:", lastResortLoc)
                  persistFoodUserLocation(lastResortLoc)
                  setLocation(lastResortLoc)
                  setPermissionGranted(true)
                  if (showLoading) setLoading(false)
                  setError(null)
                  if (updateDB) await updateLocationInDB(lastResortLoc).catch(() => { })
                  resolve(lastResortLoc)
                  return
                } else {
                  debugWarn("?? Last resort geocoding returned invalid data:", lastResortAddr)
                }
              } catch (lastErr) {
                debugError("? Last resort geocoding also failed:", lastErr.message)
              }

              // If all geocoding fails, use placeholder but don't save
              const fallbackLoc = {
                latitude,
                longitude,
                city: "Current Location",
                area: "",
                state: "",
                address: "Select location", // Don't show coordinates
                formattedAddress: "Select location", // Don't show coordinates
              }
              // Don't save placeholder values to localStorage
              // Only set in state for display
              debugWarn("?? Skipping save - all geocoding failed, using placeholder")
              setLocation(fallbackLoc)
              setPermissionGranted(true)
              if (showLoading) setLoading(false)
              // Don't try to update DB with placeholder
              resolve(fallbackLoc)
            }
          },
          async (err) => {
            // If timeout and we haven't retried yet, try with lower accuracy
            if (err.code === 3 && retryCount === 0 && options.enableHighAccuracy) {
              debugWarn("?? High accuracy timeout, retrying with lower accuracy...")
              // Retry with lower accuracy - faster response (uses network-based location)
              getPositionWithRetry({
                enableHighAccuracy: false,
                timeout: forceFresh ? 12000 : 8000,
                maximumAge: forceFresh ? 0 : 300000,
              }, 1).then(resolve).catch(reject)
              return
            }

            // Don't log timeout errors as errors - they're expected in some cases
            if (err.code === 3) {
              debugWarn("?? Geolocation timeout (code 3) - using fallback location")
            } else {
              debugError("? Geolocation error:", err.code, err.message)
            }

            // Explicit user action must not silently reuse stale cached coordinates.
            if (forceFresh && showLoading) {
              setPermissionGranted(false)
              if (showLoading) setGlobalLocationLoading(false)
              reject(err)
              return
            }

            // Try multiple fallback strategies
            try {
              // Strategy 1: Use DB location if available
              let fallback = dbLocation
              if (!fallback) {
                fallback = await fetchLocationFromDB()
              }

              // Strategy 2: Use cached location from localStorage
              if (!fallback) {
                const stored = localStorage.getItem("userLocation")
                if (stored) {
                  try {
                    fallback = JSON.parse(stored)
                    debugLog("? Using cached location from localStorage")
                  } catch (parseErr) {
                    debugWarn("?? Failed to parse stored location:", parseErr)
                  }
                }
              }

              if (fallback) {
                debugLog("? Using fallback location:", fallback)
                setLocation(fallback)
                // Don't set error for timeout when we have fallback
                if (err.code !== 3) {
                  setError(err.message)
                }
                setPermissionGranted(true) // Still grant permission if we have location
                if (showLoading) setGlobalLocationLoading(false)
                resolve(fallback)
              } else {
                // No fallback available - set a default location so UI doesn't hang
                debugWarn("?? No fallback location available, setting default")
                const defaultLocation = {
                  city: "Select location",
                  address: "Select location",
                  formattedAddress: "Select location"
                }
                setLocation(defaultLocation)
                setError(err.code === 3 ? "Location request timed out. Please try again." : err.message)
                setPermissionGranted(false)
                if (showLoading) setGlobalLocationLoading(false)
                resolve(defaultLocation) // Always resolve with something
              }
            } catch (fallbackErr) {
              debugWarn("?? Fallback retrieval failed:", fallbackErr)
              setLocation(null)
              setError(err.code === 3 ? "Location request timed out. Please try again." : err.message)
              setPermissionGranted(false)
              if (showLoading) setLoading(false)
              resolve(null)
            }
          },
          options
        )
      })
    }

    // Try with high accuracy first
    // If forceFresh is true, don't use cached location (maximumAge: 0)
    // Otherwise, allow cached location for faster response
    return getPositionWithRetry({
      enableHighAccuracy: true,
      timeout: forceFresh ? 15000 : 10000,
      maximumAge: forceFresh ? 0 : 120000,
    })
  }

  /* ===================== WATCH LOCATION ===================== */
  const startWatchingLocation = () => {
    if (!navigator.geolocation) {
      debugWarn("?? Geolocation not supported")
      return
    }

    // Clear any existing watch
    if (watchIdRef.current) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }

    debugLog("?? Starting to watch location for live updates...")

    let retryCount = 0
    const maxRetries = 2

    const startWatch = (options) => {
      watchIdRef.current = navigator.geolocation.watchPosition(
        async (pos) => {
          try {
            const { latitude, longitude, accuracy } = pos.coords
            debugLog("?? Location updated:", { latitude, longitude, accuracy: `${accuracy}m` })

            // Reset retry count on success
            retryCount = 0

            // Validate coordinates are in India range BEFORE attempting geocoding
            // India: Latitude 6.5° to 37.1° N, Longitude 68.7° to 97.4° E
            const isInIndiaRange = latitude >= 6.5 && latitude <= 37.1 && longitude >= 68.7 && longitude <= 97.4 && longitude > 0

            // "Geocode once" mode:
            // Do NOT reverse-geocode on every watch tick (it causes frequent api-bdc.io calls).
            // Instead reuse the last resolved address (from the initial page load / explicit request).
            let addr
            if (!isInIndiaRange || longitude < 0) {
              debugWarn("?? Coordinates outside India range; skipping reverse geocoding:", { latitude, longitude })
              addr = {
                city: "Current Location",
                state: "",
                country: "",
                area: "",
                address: "Select location",
                formattedAddress: "Select location",
              }
            } else if (lastResolvedAddressRef.current && lastResolvedAddressRef.current.formattedAddress) {
              addr = lastResolvedAddressRef.current
            } else {
              // If we don't have an address yet, avoid network calls and keep placeholders.
              // (The initial location fetch should set `lastResolvedAddressRef`.)
              addr = {
                city: "Current Location",
                state: "",
                country: "",
                area: "",
                address: "Select location",
                formattedAddress: "Select location",
              }
            }

            // CRITICAL: Ensure formattedAddress is NEVER coordinates
            // Check if reverse geocoding returned proper address or just coordinates
            let completeFormattedAddress = addr.formattedAddress || "";
            let displayAddress = addr.address || "";

            // Check if formattedAddress is coordinates pattern
            const isFormattedAddressCoordinates = /^-?\d+\.\d+,\s*-?\d+\.\d+$/.test(completeFormattedAddress.trim());
            const isDisplayAddressCoordinates = /^-?\d+\.\d+,\s*-?\d+\.\d+$/.test(displayAddress.trim());

            // If formattedAddress is coordinates, it means reverse geocoding failed
            // Build proper address from components or use fallback
            if (isFormattedAddressCoordinates || !completeFormattedAddress || completeFormattedAddress === "Select location") {
              debugWarn("?????? Reverse geocoding returned coordinates or empty address!")
              debugWarn("?? Attempting to build address from components:", {
                city: addr.city,
                state: addr.state,
                area: addr.area,
                street: addr.street,
                streetNumber: addr.streetNumber
              })

              // Build address from components
              const addressParts = [];
              if (addr.area && addr.area.trim() !== "") {
                addressParts.push(addr.area);
              }
              if (addr.city && addr.city.trim() !== "") {
                addressParts.push(addr.city);
              }
              if (addr.state && addr.state.trim() !== "") {
                addressParts.push(addr.state);
              }

              if (addressParts.length > 0) {
                completeFormattedAddress = addressParts.join(', ');
                displayAddress = addr.area || addr.city || "Select location";
                debugLog("? Built address from components:", completeFormattedAddress);
              } else {
                // Final fallback - don't use coordinates
                completeFormattedAddress = addr.city || "Select location";
                displayAddress = addr.city || "Select location";
                debugWarn("?? Using fallback address:", completeFormattedAddress);
              }
            }

            // Also check displayAddress
            if (isDisplayAddressCoordinates) {
              displayAddress = addr.area || addr.city || "Select location";
            }

            // Build location object with ALL fields from reverse geocoding
            // NEVER include coordinates in formattedAddress or address
            const loc = {
              ...addr, // This includes: city, state, area, street, streetNumber, postalCode
              latitude,
              longitude,
              accuracy: accuracy || null,
              address: displayAddress, // Locality parts for navbar display (NEVER coordinates)
              formattedAddress: completeFormattedAddress // Complete detailed address (NEVER coordinates)
            }

            // STABILITY: Only update if location changed significantly (>10m) OR address improved
            const currentLoc = location
            if (currentLoc && currentLoc.latitude && currentLoc.longitude) {
              // Calculate distance in meters (Haversine formula simplified for small distances)
              const latDiff = latitude - currentLoc.latitude
              const lngDiff = longitude - currentLoc.longitude
              const distanceMeters = Math.sqrt(latDiff * latDiff + lngDiff * lngDiff) * 111320 // ~111320m per degree

              // Check if address is better (more parts = more complete)
              const currentParts = (currentLoc.formattedAddress || "").split(',').filter(p => p.trim()).length
              const newParts = completeFormattedAddress.split(',').filter(p => p.trim()).length
              const addressImproved = newParts > currentParts

              // Only update if moved >10 meters OR address significantly improved
              if (distanceMeters <= 10 && !addressImproved) {
                debugLog(`?? Location unchanged (${distanceMeters.toFixed(1)}m change), keeping stable address`)
                return // Don't update - keep current stable address
              }

              debugLog(`?? Location updated: ${distanceMeters.toFixed(1)}m change, address parts: ${currentParts} ? ${newParts}`)
            }

            // Final validation - ensure formattedAddress is never coordinates
            if (loc.formattedAddress && /^-?\d+\.\d+,\s*-?\d+\.\d+$/.test(loc.formattedAddress.trim())) {
              debugError("??? CRITICAL: formattedAddress is still coordinates! Replacing with city/area")
              loc.formattedAddress = loc.area || loc.city || "Select location";
              loc.address = loc.area || loc.city || "Select location";
            }

            // Check if location has placeholder values - don't save placeholders
            const hasPlaceholder =
              loc.city === "Current Location" ||
              loc.address === "Select location" ||
              loc.formattedAddress === "Select location" ||
              (!loc.city && !loc.address && !loc.formattedAddress && !loc.area);

            if (hasPlaceholder) {
              debugWarn("?? Skipping live location update - contains placeholder values:", loc)
              return // Don't update location or save to DB
            }

            // Check if coordinates have changed significantly (threshold: ~10 meters)
            const coordThreshold = 0.0001 // approximately 10 meters
            const coordsChanged =
              !prevLocationCoordsRef.current.latitude ||
              !prevLocationCoordsRef.current.longitude ||
              Math.abs(prevLocationCoordsRef.current.latitude - loc.latitude) > coordThreshold ||
              Math.abs(prevLocationCoordsRef.current.longitude - loc.longitude) > coordThreshold
            let persistedLocation = loc
            try {
              const storedRaw = localStorage.getItem("userLocation")
              const storedLocation = storedRaw ? JSON.parse(storedRaw) : null
              const savedLabel = loc?.label || storedLocation?.label
              if (savedLabel && String(savedLabel).trim()) {
                persistedLocation = { ...loc, label: String(savedLabel).trim() }
              }
            } catch {
              persistedLocation = loc
            }

            // Only update location state if coordinates changed significantly
            if (coordsChanged) {
              prevLocationCoordsRef.current = { latitude: loc.latitude, longitude: loc.longitude }
              debugLog("?? Updating live location:", loc)
              persistFoodUserLocation(persistedLocation)
              setLocation(persistedLocation)
              setPermissionGranted(true)
              setError(null)
            } else {
              // Coordinates haven't changed significantly, skip state update to prevent re-renders
              // Still update localStorage silently for persistence
              persistFoodUserLocation(persistedLocation)
            }

            // Debounce DB updates - only update every 5 seconds
            clearTimeout(updateTimerRef.current)
            updateTimerRef.current = setTimeout(() => {
              updateLocationInDB(loc).catch(err => {
                debugWarn("Failed to update location in DB:", err)
              })
            }, 5000)
          } catch (err) {
            debugError("? Error processing live location update:", err)
            // If reverse geocoding fails, DON'T use coordinates - use placeholder
            const { latitude, longitude } = pos.coords
            const fallbackLoc = {
              latitude,
              longitude,
              city: "Current Location",
              area: "",
              state: "",
              address: "Select location", // NEVER use coordinates
              formattedAddress: "Select location", // NEVER use coordinates
            }
            debugWarn("?? Using fallback location (reverse geocoding failed):", fallbackLoc)
            // Don't save placeholder values to localStorage
            // Only set in state for display
            debugWarn("?? Skipping localStorage save - fallback location contains placeholder values")
            setLocation(fallbackLoc)
            setPermissionGranted(true)
          }
        },
        (err) => {
          // Don't log timeout errors for watchPosition (it's a background operation)
          // Only log non-timeout errors
          if (err.code !== 3) {
            debugWarn("?? Watch position error (non-timeout):", err.code, err.message)
          }

          // If timeout and we haven't exceeded max retries, retry with HIGH ACCURACY GPS
          // CRITICAL: Keep using GPS (not network-based) for accurate location
          // Network-based location won't give exact landmarks like "Mama Loca Cafe"
          if (err.code === 3 && retryCount < maxRetries) {
            retryCount++
            debugLog(`?? GPS timeout, retrying with high accuracy GPS (attempt ${retryCount}/${maxRetries})...`)

            // Clear current watch
            if (watchIdRef.current) {
              navigator.geolocation.clearWatch(watchIdRef.current)
              watchIdRef.current = null
            }

            // Retry with HIGH ACCURACY GPS (don't use network-based location)
            // Network-based location is less accurate and won't give exact landmarks
            setTimeout(() => {
              startWatch({
                enableHighAccuracy: true,   // Keep using GPS (not network-based)
                timeout: 20000,              // 20 seconds timeout (give GPS more time)
                maximumAge: 0                // Always get fresh GPS location
              })
            }, 3000) // 3 second delay before retry
            return
          }

          // If all retries failed, silently continue - don't set error state for background watch
          // The watch will keep trying in background, user won't notice
          // Only set error for non-timeout errors that are critical
          if (err.code !== 3) {
            setError(err.message)
            setPermissionGranted(false)
          }

          // Don't clear the watch - let it keep trying in background
          // The user might move to a location with better GPS signal
        },
        options
      )
    }

    // Start with HIGH ACCURACY GPS for live location tracking
    // CRITICAL: enableHighAccuracy: true forces GPS (not network-based) for accurate location
    // Network-based location won't give exact landmarks like "Mama Loca Cafe"
    startWatch({
      enableHighAccuracy: true,   // CRITICAL: Use GPS (not network-based) for accurate location
      timeout: 15000,             // 15 seconds timeout (gives GPS more time to get accurate fix)
      maximumAge: 0               // Always get fresh GPS location (no cache for live tracking)
    })

    debugLog("??? GPS High Accuracy enabled for live location tracking")
    debugLog("? GPS will provide accurate coordinates for reverse geocoding")
    debugLog("? Network-based location disabled (less accurate)")
  }

  const stopWatchingLocation = () => {
    if (watchIdRef.current) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    clearTimeout(updateTimerRef.current)
  }

  const refreshLocationIfPermitted = async ({ showLoading = false } = {}) => {
    if (isDefaultLocationMode || !navigator.geolocation) return null

    let permissionState = "unknown"
    if (navigator.permissions?.query) {
      try {
        const result = await navigator.permissions.query({ name: "geolocation" })
        permissionState = result.state
        if (permissionState === "denied") return null
      } catch {
        permissionState = "unknown"
      }
    }

    const hasPriorSavedLocation = hasValidStoredUserLocation()

    // First visit: wait for the location popup button so we don't trigger a browser prompt on load.
    if (permissionState !== "granted" && !hasPriorSavedLocation) {
      return null
    }

    try {
      if (showLoading) setGlobalLocationLoading(true)
      const loc = await getLocation(true, true, showLoading)
      if (loc && !isPlaceholderLocation(loc)) {
        setLocation(loc)
        setPermissionGranted(true)
        window.dispatchEvent(new CustomEvent("userLocationUpdated"))
      }
      return loc
    } catch (err) {
      debugWarn("Background location refresh failed:", err?.message || err)
      return null
    } finally {
      if (showLoading) setGlobalLocationLoading(false)
    }
  }

  // Default Location Mode switched ON (also when it arrives after the first paint): replace a location taken from the
  // device GPS earlier with Indore. An address the customer picked themselves ("saved" mode) is left alone.
  useEffect(() => {
    if (!isDefaultLocationMode) return
    try {
      const stored = JSON.parse(localStorage.getItem("userLocation") || "null")
      const alreadyIndore =
        stored?.latitude === TEMPORARY_DEFAULT_INDORE_LOCATION.latitude &&
        stored?.longitude === TEMPORARY_DEFAULT_INDORE_LOCATION.longitude
      if (alreadyIndore) return
      if (stored && localStorage.getItem("deliveryAddressMode") === "saved") return
      persistFoodUserLocation(TEMPORARY_DEFAULT_INDORE_LOCATION)
      setLocation(TEMPORARY_DEFAULT_INDORE_LOCATION)
      setLoading(false)
      window.dispatchEvent(new CustomEvent("userLocationUpdated"))
    } catch {
      /* ignore */
    }
  }, [isDefaultLocationMode])

  /* ===================== INIT ===================== */
  useEffect(() => {
    // Check if location should be suppressed on the current path/auth state
    const pathname = getAppRoutePath().toLowerCase();
    const isSuppressedPath = 
      pathname.includes('terms') ||
      pathname.includes('privacy') ||
      pathname.includes('support') ||
      pathname.includes('login') ||
      pathname.includes('otp');

    const isAuthenticated = !!(localStorage.getItem('user_accessToken') || localStorage.getItem('accessToken'));

    // Load stored location first for IMMEDIATE display (no loading state)
    const stored = localStorage.getItem("userLocation")
    let shouldForceRefresh = false
    let hasInitialLocation = false

    if (stored) {
      try {
        const parsedLocation = JSON.parse(stored)

        // Show cached location immediately.
        // Requirement: only geocode again on explicit manual change.
        const lat = Number(parsedLocation?.latitude)
        const lng = Number(parsedLocation?.longitude)
        const hasLatLng = Number.isFinite(lat) && Number.isFinite(lng)

        if (parsedLocation && hasLatLng) {
          setLocation(parsedLocation)
          setPermissionGranted(true)
          setLoading(false) // Set loading to false immediately
          hasInitialLocation = true
          shouldForceRefresh = false
          debugLog("?? Loaded stored location instantly (no auto-refresh):", parsedLocation)
        } else {
          // If we don't have usable coordinates, we must fetch once on first open.
          debugLog("?? Stored location missing coordinates; will fetch once")
          shouldForceRefresh = true
        }
      } catch (err) {
        debugError("Failed to parse stored location:", err)
        shouldForceRefresh = true
      }
    } else {
      if (isDefaultLocationMode) {
        // TEMPORARY: No stored location found - set default Indore in localStorage
        // This ensures PageNavbar and other components see the default immediately.
        try {
          persistFoodUserLocation(TEMPORARY_DEFAULT_INDORE_LOCATION)
          setLocation(TEMPORARY_DEFAULT_INDORE_LOCATION)
          setLoading(false)
          hasInitialLocation = true
          debugLog("?? TEMPORARY: Set default Indore location in localStorage")
        } catch (e) {
          debugError("Failed to set default Indore location:", e)
        }
      }
    }

    // If no cached location, try DB (only if authenticated and path is not suppressed)
    if (!hasInitialLocation && !isSuppressedPath && isAuthenticated) {
      fetchLocationFromDB()
        .then((dbLoc) => {
          if (dbLoc && Number.isFinite(Number(dbLoc.latitude)) && Number.isFinite(Number(dbLoc.longitude))) {
            setLocation(dbLoc)
            setPermissionGranted(true)
            setGlobalLocationLoading(false)
            hasInitialLocation = true
            debugLog("?? Loaded location from DB:", dbLoc)
          } else {
            // No location found - set loading to false and show fallback
            setGlobalLocationLoading(false)
            shouldForceRefresh = true
          }
        })
        .catch(() => {
          setGlobalLocationLoading(false)
          shouldForceRefresh = true
        })
    } else if (!isAuthenticated || isSuppressedPath) {
      setGlobalLocationLoading(false)
    }

    // Always ensure loading is false after initial check
    // Safety timeout to prevent infinite loading
    const loadingTimeout = setTimeout(() => {
      setLoading((currentLoading) => {
        if (currentLoading) {
          debugWarn("?? Loading timeout - setting loading to false")
          // Only set fallback if we still don't have a location
          setLocation((currentLocation) => {
            if (!currentLocation ||
              (currentLocation.formattedAddress === "Select location" &&
                !currentLocation.latitude && !currentLocation.city)) {
              if (isDefaultLocationMode) {
                return TEMPORARY_DEFAULT_INDORE_LOCATION
              } else {
                return {
                  city: "Select location",
                  address: "Select location",
                  formattedAddress: "Select location"
                }
              }
            }
            return currentLocation
          })
        }
        return false
      })
    }, 5000) // 5 second safety timeout

    // Fresh tab/app open → force current GPS (F5 keeps selected city via isNewAppSession=false).
    const startAutoLocationRefresh = () => {
      runDedupedAutoRefresh(() => refreshLocationIfPermitted({ showLoading: false }))
    }

    if (!isDefaultLocationMode && !isSuppressedPath && isNewAppSession) {
      if (!pageLoadAutoRefreshStarted) {
        pageLoadAutoRefreshStarted = true
        try {
          // "manual_location_update" is what makes Food's screen show the blocking "Fetching Location..." cover.
          // This hook also runs while the user is on a Taxi screen (it is mounted at the app root), where that flag
          // would just sit there and pop the cover up the moment they switch to Food - so only raise it on Food.
          if (getAppRoutePath().startsWith("/food")) {
            sessionStorage.setItem("manual_location_update", "true")
          }
          localStorage.setItem("deliveryAddressMode", "current")
          window.dispatchEvent(new CustomEvent("deliveryAddressModeUpdated"))
        } catch {}
        // requestLocation clears the prior city pin and pulls live GPS (not a silent cache hit).
        runDedupedAutoRefresh(() =>
          requestLocation()
            .catch((err) => {
              debugError("New-tab current location fetch failed, falling back:", err)
              return refreshLocationIfPermitted({ showLoading: true })
            })
            // The fix is in (or failed): the cover must not stay armed for a later screen.
            .finally(() => {
              try {
                sessionStorage.removeItem("manual_location_update")
              } catch {}
            }),
        )
      }
    } else {
      setLoading(false)
      // Reloaded before the first GPS fix was saved (e.g. right after login):
      // nothing is cached and nothing else would fetch it, so the app stayed on
      // "Select location". Silent — only runs if permission is already granted.
      if (!hasInitialLocation && !isDefaultLocationMode && !isSuppressedPath && isAuthenticated) {
        startAutoLocationRefresh()
      }
    }

    // Listen for storage changes to keep location in sync across components/tabs
    const handleStorageChange = (e) => {
      if (e.key === "userLocation" && e.newValue) {
        try {
          const newLoc = JSON.parse(e.newValue)
          setLocation(newLoc)
          debugLog("?? Location updated from storage event:", newLoc)
        } catch (err) {
          debugError("Failed to parse location from storage event:", err)
        }
      }
    }

    // Also listen for custom event that might be fired within the same window
    const handleCustomUpdate = () => {
      const stored = localStorage.getItem("userLocation")
      if (stored) {
        try {
          const newLoc = JSON.parse(stored)
          setLocation(newLoc)
          debugLog("?? Location updated from custom update event:", newLoc)
        } catch {}
      }
    }

    window.addEventListener('storage', handleStorageChange)
    window.addEventListener('userLocationUpdated', handleCustomUpdate)

    // Auto-fetch current location on login (even if this tab already had a session).
    const handleLoginSuccess = () => {
      if (isDefaultLocationMode) {
        debugLog("?? Default Location Mode is active. Suppressing login success location fetch.")
        return
      }

      const hasFetchedThisLogin = sessionStorage.getItem('lastLoginLocationFetch');
      if (hasFetchedThisLogin) return;

      debugLog("?? Login success, triggering one-time automatic location fetch...")
      try {
        sessionStorage.setItem(LOCATION_APP_SESSION_KEY, "1")
        localStorage.setItem("deliveryAddressMode", "current")
        window.dispatchEvent(new CustomEvent("deliveryAddressModeUpdated"))
      } catch {}
      setTimeout(() => {
        requestLocation().then(() => {
          sessionStorage.setItem('lastLoginLocationFetch', 'true');
        }).catch(err => {
          debugError("Failed to auto-fetch location after login:", err)
        })
      }, 1000)
    }

    window.addEventListener('userLoginSuccess', handleLoginSuccess)

    // Cleanup timeout and watcher
    return () => {
      clearTimeout(loadingTimeout)
      debugLog("?? Cleaning up location watcher")
      stopWatchingLocation()
      window.removeEventListener('storage', handleStorageChange)
      window.removeEventListener('userLocationUpdated', handleCustomUpdate)
      window.removeEventListener('userLoginSuccess', handleLoginSuccess)
    }
  }, [])

  const requestLocation = async () => {
    debugLog("?????? User requested location update - clearing cache and fetching fresh")
    setGlobalLocationLoading(true)
    setError(null)

    try {
      try {
        localStorage.setItem("deliveryAddressMode", "current")
        window.dispatchEvent(new CustomEvent("deliveryAddressModeUpdated"))
      } catch {}

      // Clear cached location to force fresh fetch
      localStorage.removeItem("userLocation")
      debugLog("??? Cleared cached location from localStorage")

      // Show loading, so pass showLoading = true
      // forceFresh = true, updateDB = true, showLoading = true
      // This ensures we get fresh GPS coordinates and reverse geocode
      const location = await getLocation(true, true, true)

      debugLog("??? Fresh location requested successfully:", location)
      debugLog("??? Complete Location details:", {
        formattedAddress: location?.formattedAddress,
        address: location?.address,
        city: location?.city,
        state: location?.state,
        area: location?.area,
        pointOfInterest: location?.pointOfInterest,
        premise: location?.premise,
        coordinates: location?.latitude && location?.longitude ?
          `${location.latitude.toFixed(8)}, ${location.longitude.toFixed(8)}` : "N/A",
        hasCompleteAddress: location?.formattedAddress &&
          location.formattedAddress !== "Select location" &&
          !location.formattedAddress.match(/^-?\d+\.\d+,\s*-?\d+\.\d+$/) &&
          location.formattedAddress.split(',').length >= 4
      })

      // Verify we got complete address (POI, building, floor, area, city, state, pincode)
      if (!location?.formattedAddress ||
        location.formattedAddress === "Select location" ||
        location.formattedAddress.match(/^-?\d+\.\d+,\s*-?\d+\.\d+$/) ||
        location.formattedAddress.split(',').length < 4) {
        debugWarn("?????? Location received but address is incomplete!")
        debugWarn("?? Address parts count:", location?.formattedAddress?.split(',').length || 0)
        debugWarn("?? This might be due to:")
        debugWarn("   1. Geocoding service unavailable or rate-limited")
        debugWarn("   2. Location permission not granted")
        debugWarn("   3. GPS accuracy too low (try on mobile device)")
      } else {
        debugLog("??? SUCCESS: Complete detailed address received!")
        debugLog("? Full address:", location.formattedAddress)
      }

      // Dispatch custom event to notify all other mounted hook instances (Navbar, Home, etc.)
      try {
        window.dispatchEvent(new CustomEvent("userLocationUpdated"))
      } catch (evtErr) {
        debugWarn("Failed to dispatch custom event:", evtErr)
      }

      return location
    } catch (err) {
      debugError("? Failed to request location:", err)
      setError(err.message || "Failed to get location")
      throw err
    } finally {
      setGlobalLocationLoading(false)
    }
  }

  /**
   * Fast path for Address Selector "Use current location".
   * - Does not clear cache first
   * - Prefers recent GPS (≤30s) + low-accuracy first (much faster)
   * - Single reverse-geocode, DB update in background
   */
  const requestLocationFast = async () => {
    setError(null)

    if (!navigator.geolocation) {
      throw new Error("Geolocation not supported")
    }

    try {
      try {
        localStorage.setItem("deliveryAddressMode", "current")
        window.dispatchEvent(new CustomEvent("deliveryAddressModeUpdated"))
      } catch {}

      const getPosition = (options) =>
        new Promise((resolve, reject) => {
          getFastAccuratePosition(resolve, reject, options)
        })

      let pos
      try {
        // Fast path: network/wifi location + accept a recent fix
        pos = await getPosition({
          enableHighAccuracy: false,
          timeout: 6000,
          maximumAge: 30000,
        })
      } catch {
        // Fallback: true GPS if low-accuracy fails
        pos = await getPosition({
          enableHighAccuracy: true,
          timeout: 10000,
          maximumAge: 0,
        })
      }

      const { latitude, longitude, accuracy } = pos.coords
      if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
        throw new Error("Invalid coordinates")
      }

      let addr
      try {
        addr = await reverseGeocodeWithGoogleMaps(latitude, longitude)
      } catch {
        addr = await reverseGeocodeDirect(latitude, longitude)
      }

      const finalLoc = {
        ...addr,
        city: resolveServiceCity({
          locality: addr?.city || "",
          formattedAddress: addr?.formattedAddress || addr?.address || "",
          fallback: addr?.city || "Indore",
        }),
        latitude,
        longitude,
        accuracy: accuracy ?? null,
      }

      persistFoodUserLocation(finalLoc)
      setLocation(finalLoc)
      setPermissionGranted(true)

      // Don't block UI on DB write
      updateLocationInDB(finalLoc).catch(() => {})

      try {
        window.dispatchEvent(new CustomEvent("userLocationUpdated"))
      } catch {}

      return finalLoc
    } catch (err) {
      debugError("? Fast location request failed:", err)
      setError(err.message || "Failed to get location")
      throw err
    }
  }

  const { getDefaultAddress } = useProfile()
  const defaultSavedAddress = getDefaultAddress?.() || null

  const defaultSavedAddressLocation = useMemo(() => {
    if (!defaultSavedAddress) return null
    const coordinates = defaultSavedAddress?.location?.coordinates
    if (Array.isArray(coordinates) && coordinates.length >= 2) {
      const lng = parseFloat(coordinates[0])
      const lat = parseFloat(coordinates[1])
      if (Number.isFinite(lat) && Number.isFinite(lng)) {
        return { latitude: lat, longitude: lng }
      }
    }

    const lat = parseFloat(defaultSavedAddress?.latitude || defaultSavedAddress?.lat)
    const lng = parseFloat(defaultSavedAddress?.longitude || defaultSavedAddress?.lng)
    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      return { latitude: lat, longitude: lng }
    }

    return null
  }, [defaultSavedAddress])

  // Listen to deliveryAddressMode changes using a local state
  const [addressMode, setAddressMode] = useState(() => {
    try {
      // New app/tab sessions force "current"; same-session refresh keeps prior mode.
      return localStorage.getItem("deliveryAddressMode") || "current"
    } catch {
      return "current"
    }
  })

  useEffect(() => {
    const handleModeUpdate = () => {
      try {
        setAddressMode(localStorage.getItem("deliveryAddressMode") || "current")
      } catch {}
    }
    window.addEventListener("userLocationUpdated", handleModeUpdate)
    window.addEventListener("deliveryAddressModeUpdated", handleModeUpdate)
    return () => {
      window.removeEventListener("userLocationUpdated", handleModeUpdate)
      window.removeEventListener("deliveryAddressModeUpdated", handleModeUpdate)
    }
  }, [])

  const effectiveLocation = useMemo(() => {
    if (addressMode === "current") {
      return location
    }

    if (
      defaultSavedAddressLocation &&
      Number.isFinite(defaultSavedAddressLocation.latitude) &&
      Number.isFinite(defaultSavedAddressLocation.longitude)
    ) {
      const parts = [
        defaultSavedAddress?.additionalDetails,
        defaultSavedAddress?.street,
        defaultSavedAddress?.city,
        defaultSavedAddress?.state,
        defaultSavedAddress?.zipCode,
      ].filter(Boolean)

      const resolvedAddress = parts.length > 0 ? parts.join(", ") : defaultSavedAddress?.formattedAddress || defaultSavedAddress?.address || ""

      return {
        ...(location || {}),
        latitude: defaultSavedAddressLocation.latitude,
        longitude: defaultSavedAddressLocation.longitude,
        area: defaultSavedAddress?.additionalDetails || defaultSavedAddress?.street || defaultSavedAddress?.area || "",
        city: defaultSavedAddress?.city || "",
        state: defaultSavedAddress?.state || "",
        address: resolvedAddress,
        formattedAddress: resolvedAddress,
        pincode: defaultSavedAddress?.zipCode || "",
      }
    }

    return location
  }, [location, defaultSavedAddressLocation, addressMode, defaultSavedAddress])

  return {
    location: effectiveLocation,
    geoLocation: location,
    effectiveLocation,
    loading,
    error,
    permissionGranted,
    requestLocation,
    requestLocationFast,
    startWatchingLocation,
    stopWatchingLocation,
  }
}

import { useEffect, useRef, useState, useCallback } from 'react';
import io from 'socket.io-client';
import { toast } from '@/lib/toast';
import { API_BASE_URL } from '@food/api/config';
import { restaurantAPI } from '@food/api';
import { dispatchNotificationInboxRefresh } from '@food/hooks/useNotificationInbox';
import {
  isNativeAppWebView,
  shouldSkipDuplicateOsNotification,
} from '@food/utils/firebaseMessaging';
import { normalizeRestaurantOrderView } from '@food/utils/restaurantOrderPricing';
import { getAppRoutePath } from '@/shared/utils/nativeShell';

const alertSound = '/assets/media/restaurant_alert.mp3';
const debugLog = (...args) => {};
const debugWarn = (...args) => {};
const debugError = (...args) => {};

let cachedAudioBlobUrl = null;
const preloadAudio = async () => {
  if (cachedAudioBlobUrl) return cachedAudioBlobUrl;
  try {
    const response = await fetch(alertSound);
    if (response.ok) {
      const blob = await response.blob();
      cachedAudioBlobUrl = URL.createObjectURL(blob);
      return cachedAudioBlobUrl;
    }
  } catch (e) {
    debugWarn('Failed to preload audio blob:', e);
  }
  return alertSound;
};

// Do NOT preload on import — this hook is imported from shared Food routes,
// and eager fetch() would load restaurant_alert.mp3 on user/delivery pages too.

const resolveAudioSource = (source) => {
  return cachedAudioBlobUrl || source;
};

const supportsBrowserNotifications = () =>
  typeof window !== 'undefined' && typeof Notification !== 'undefined';

const buildRestaurantOrderNotification = (orderData = {}) => {
  const orderId = orderData.orderId || orderData.orderMongoId || 'New';
  const itemCount = Array.isArray(orderData.items) ? orderData.items.length : 0;
  const total = Number(orderData.total || orderData.pricing?.total || 0);

  return {
    title: `New order #${orderId}`,
    body: itemCount > 0
      ? `${itemCount} item${itemCount === 1 ? '' : 's'} - ₹${total.toFixed(2)}`
      : 'A new order is waiting for review',
    tag: `restaurant-order-${orderId}`,
    data: {
      orderId,
      targetUrl: `/restaurant/orders/${orderData.orderMongoId || orderData.orderId || ''}`,
    },
  };
};

// The Flutter shell's ringtone bridge does not exist in the native app; the OS notification (FCM) carries the alert.
const triggerWebViewNativeNotification = async (orderData = {}) => {
  void orderData;
  return false;
};

const stopWebViewNativeNotification = async () => {};

// --------------------------------------------------------------------------
// GLOBAL SINGLETON STATE (Shared across all component hook instances)
// --------------------------------------------------------------------------
let globalNativeRingCleared = false;
let globalIsMuted = false;
if (typeof window !== 'undefined') {
  globalIsMuted = localStorage.getItem('restaurant_notifications_muted') === 'true';
}

let globalMutedOrderIds = new Set();
if (typeof window !== 'undefined') {
  try {
    const saved = localStorage.getItem('restaurant_muted_order_ids');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        globalMutedOrderIds = new Set(parsed);
      }
    }
  } catch (e) {
    debugWarn('Failed to parse restaurant_muted_order_ids:', e);
  }
}

const saveMutedOrderIds = () => {
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem('restaurant_muted_order_ids', JSON.stringify(Array.from(globalMutedOrderIds)));
    } catch (e) {
      debugWarn('Failed to save restaurant_muted_order_ids:', e);
    }
  }
};

let globalNewOrder = null;
let globalNewReservation = null;
let globalActiveOrder = null;

// Audio player references
let globalAudio = null;
let globalFallbackAudio = null;
let globalAlertLoopTimer = null;
let globalAlertLoopStartedAt = 0;

// Socket and Polling references
let globalSocket = null;
let globalSocketConnected = false;
let globalActiveRestaurantId = null;
let globalPollingIntervalId = null;

let processedOrderIds = new Set();
if (typeof window !== 'undefined') {
  try {
    const saved = localStorage.getItem('restaurant_processed_order_ids');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        processedOrderIds = new Set(parsed);
      }
    }
  } catch (e) {}
}

const saveProcessedOrderIds = () => {
  if (typeof window !== 'undefined') {
    try {
      const arr = Array.from(processedOrderIds).slice(-200);
      localStorage.setItem('restaurant_processed_order_ids', JSON.stringify(arr));
    } catch (e) {}
  }
};

const lastAlertAtByOrder = new Map();
const lastBrowserNotificationAtByOrder = new Map();

// Hook subscribers
const subscribers = new Set();

const updateGlobalState = (updates) => {
  if ('isMuted' in updates) {
    globalIsMuted = updates.isMuted;
    localStorage.setItem('restaurant_notifications_muted', globalIsMuted ? 'true' : 'false');
  }
  if ('newOrder' in updates) {
    globalNewOrder = updates.newOrder;
  }
  if ('newReservation' in updates) {
    globalNewReservation = updates.newReservation;
  }
  if ('activeOrder' in updates) {
    globalActiveOrder = updates.activeOrder;
  }
  if ('socketConnected' in updates) {
    globalSocketConnected = updates.socketConnected;
  }

  subscribers.forEach((callback) => {
    try {
      callback({
        isMuted: globalIsMuted,
        mutedOrderIds: globalMutedOrderIds,
        newOrder: globalNewOrder,
        newReservation: globalNewReservation,
        isConnected: globalSocketConnected,
      });
    } catch (e) {
      // Ignore defunct subscribers
    }
  });
};

const stopGlobalAlertLoop = () => {
  if (globalAlertLoopTimer) {
    clearInterval(globalAlertLoopTimer);
    globalAlertLoopTimer = null;
  }
  globalAlertLoopStartedAt = 0;

  if (typeof window !== 'undefined') {
    try {
      const keys = Array.from({ length: localStorage.length }, (_, i) => localStorage.key(i)).filter(Boolean);
      keys.forEach(k => {
        if (k.startsWith('alert_start_')) {
          localStorage.removeItem(k);
        }
      });
    } catch (_) {}
  }

  if (globalAudio) {
    try {
      globalAudio.pause();
      globalAudio.currentTime = 0;
    } catch (_) {}
  }
  if (globalFallbackAudio) {
    try {
      globalFallbackAudio.pause();
      globalFallbackAudio.currentTime = 0;
    } catch (_) {}
    globalFallbackAudio = null;
  }
  stopWebViewNativeNotification();
};

const playGlobalNotificationSound = async (orderData = {}) => {
  try {
    if (globalIsMuted || isOrderMuted(orderData)) return;
    void triggerWebViewNativeNotification(orderData).catch(() => {});
    if (typeof window !== 'undefined' && typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function') {
      try {
        navigator.vibrate([200, 100, 200, 100, 300]);
      } catch (_) {}
    }

    if (!globalAudio && typeof window !== 'undefined') {
      globalAudio = new Audio();
      globalAudio.preload = 'auto';
      globalAudio.volume = 1;
      preloadAudio().then(src => {
        if (globalAudio) {
          globalAudio.src = src;
        }
      });
    }

    if (globalAudio) {
      globalAudio.muted = false;
      globalAudio.volume = 1;
      globalAudio.currentTime = 0;
      globalAudio.play().catch(error => {
        if (!error.message?.includes("user didn't interact") && !error.name?.includes('NotAllowedError')) {
          try {
            if (globalFallbackAudio) {
              globalFallbackAudio.pause();
              globalFallbackAudio = null;
            }
            globalFallbackAudio = new Audio(resolveAudioSource(alertSound));
            globalFallbackAudio.volume = 1;
            globalFallbackAudio.muted = false;
            globalFallbackAudio.play().catch(() => {});
          } catch (fallbackError) {
            // ignore
          }
        }
      });
    }
  } catch (error) {
    // ignore
  }
};

// Rings until the order is accepted / rejected / cancelled, the restaurant
// mutes it, or the popup closes (each of those calls stopGlobalAlertLoop).
// There used to be a 2-minute cap, persisted per order in localStorage, so an
// order opened late popped up silently.
// Table (dining) requests ring like orders do, until the restaurant opens or dismisses the popup.
let globalDiningLoopTimer = null;
const stopDiningAlertLoop = () => {
  if (globalDiningLoopTimer) {
    clearInterval(globalDiningLoopTimer);
    globalDiningLoopTimer = null;
  }
};
const startDiningAlertLoop = (bookingData) => {
  stopDiningAlertLoop();
  if (!globalIsMuted) playGlobalNotificationSound(bookingData);
  globalDiningLoopTimer = setInterval(() => {
    if (!globalNewReservation) {
      stopDiningAlertLoop();
      return;
    }
    if (!globalIsMuted) playGlobalNotificationSound(globalNewReservation);
  }, 4500);
};

const startGlobalAlertLoop = (orderData) => {
  stopGlobalAlertLoop();

  globalAlertLoopStartedAt = Date.now();
  globalActiveOrder = orderData;
  updateGlobalState({ activeOrder: orderData });

  const ALERT_LOOP_INTERVAL_MS = 4500;

  if (!globalIsMuted && !isOrderMuted(orderData)) {
    playGlobalNotificationSound(orderData);
  }

  globalAlertLoopTimer = setInterval(() => {
    if (!globalActiveOrder) {
      stopGlobalAlertLoop();
      return;
    }

    // Respect BOTH the global mute and the per-order mute — muting an order must
    // silence its alert even if the loop wasn't torn down for any reason.
    if (!globalIsMuted && !isOrderMuted(globalActiveOrder)) {
      playGlobalNotificationSound(globalActiveOrder);
    }
  }, ALERT_LOOP_INTERVAL_MS);
};

const isProcessedOrder = (orderData) => {
  if (!orderData) return false;
  const ids = [
    orderData.orderMongoId,
    orderData.orderId,
    orderData._id,
    orderData.id,
    orderData.mongoId,
    orderData.order_id,
    orderData.order_mongo_id
  ].filter(Boolean);
  return ids.some(id => processedOrderIds.has(String(id).trim()));
};

const getOrderAlertKey = (orderData = {}) => (
  String(
    orderData?.orderMongoId ||
    orderData?.order_mongo_id ||
    orderData?.orderId ||
    orderData?.order_id ||
    orderData?._id ||
    orderData?.id ||
    ''
  ).trim()
);

// True if ANY of the order's id variants is muted. Different call sites resolve
// the "order id" with slightly different priorities, so checking all variants
// avoids a mute being missed just because a different id field was stored.
const isOrderMuted = (orderData = {}) => {
  const ids = [
    orderData?.orderMongoId,
    orderData?.order_mongo_id,
    orderData?.orderId,
    orderData?.order_id,
    orderData?._id,
    orderData?.id,
  ]
    .map((v) => (v == null ? '' : String(v).trim()))
    .filter(Boolean);
  return ids.some((id) => globalMutedOrderIds.has(id));
};

const shouldProcessOrderAlert = (orderData = {}) => {
  const key = getOrderAlertKey(orderData);
  if (!key) return true;
  const now = Date.now();
  const last = lastAlertAtByOrder.get(key) || 0;
  const ALERT_DEDUPE_MS = 15000;
  if (now - last < ALERT_DEDUPE_MS) return false;
  lastAlertAtByOrder.set(key, now);
  return true;
};

const shouldShowBrowserNotification = (orderData = {}) => {
  const key = getOrderAlertKey(orderData);
  if (!key) return true;
  const now = Date.now();
  const last = lastBrowserNotificationAtByOrder.get(key) || 0;
  const BROWSER_NOTIFICATION_DEDUPE_MS = 20000;
  if (now - last < BROWSER_NOTIFICATION_DEDUPE_MS) return false;
  lastBrowserNotificationAtByOrder.set(key, now);
  return true;
};

const showBackgroundOrderNotification = async (orderData) => {
  if (isNativeAppWebView()) {
    return;
  }

  if (
    shouldSkipDuplicateOsNotification({
      orderMongoId: orderData?.orderMongoId || orderData?._id,
      orderId: orderData?.orderId || orderData?.order_id,
      orderStatus: orderData?.status || orderData?.orderStatus || 'new',
    })
  ) {
    return;
  }

  if (!shouldShowBrowserNotification(orderData)) {
    return;
  }

  if (!supportsBrowserNotifications() || Notification.permission !== 'granted') {
    return;
  }

  const notificationOptions = buildRestaurantOrderNotification(orderData);

  try {
    if ('serviceWorker' in navigator) {
      const registration = await navigator.serviceWorker.getRegistration();
      if (registration) {
        await registration.showNotification(notificationOptions.title, {
          body: notificationOptions.body,
          tag: notificationOptions.tag,
          renotify: false,
          requireInteraction: true,
          silent: false,
          vibrate: [200, 100, 200, 100, 300],
          data: notificationOptions.data,
        });
        return;
      }
    }

    new Notification(notificationOptions.title, {
      body: notificationOptions.body,
      tag: notificationOptions.tag,
      requireInteraction: true,
      silent: false,
      data: notificationOptions.data,
    });
  } catch (error) {
    // ignore
  }
};

/**
 * Hook for restaurant to receive real-time order notifications with sound
 * @returns {object} - { newOrder, playSound, isConnected, isMuted, setMuted, clearNewOrder, stopSound }
 */
export const useRestaurantNotifications = () => {
  const [localState, setLocalState] = useState({
    isMuted: globalIsMuted,
    mutedOrderIds: globalMutedOrderIds,
    newOrder: globalNewOrder,
    newReservation: globalNewReservation,
    isConnected: globalSocketConnected,
  });

  const [restaurantId, setRestaurantId] = useState(null);

  // Subscribe to global updates
  useEffect(() => {
    const callback = (newState) => {
      setLocalState(newState);
    };
    subscribers.add(callback);
    return () => {
      subscribers.delete(callback);
    };
  }, []);

  // Fetch restaurant ID from API on mount
  useEffect(() => {
    const fetchRestaurantId = async () => {
      try {
        const response = await restaurantAPI.getCurrentRestaurant();
        if (response.data?.success && response.data.data?.restaurant) {
          const restaurant = response.data.data.restaurant;
          if (restaurant.status !== "approved") {
            return;
          }
          const id = restaurant._id?.toString() || restaurant.restaurantId;
          setRestaurantId(id);
        }
      } catch (error) {
        // ignore
      }
    };
    fetchRestaurantId();
  }, []);

  const handleIncomingOrderAlert = useCallback((orderData, source = 'unknown') => {
    const isSocket = source === 'socket';
    const normalizedOrder = normalizeRestaurantOrderView(orderData);

    if (isProcessedOrder(normalizedOrder)) {
      return;
    }

    if (normalizedOrder?.scheduledAt) {
      const scheduledTime = new Date(normalizedOrder.scheduledAt).getTime();
      const now = Date.now();
      if (scheduledTime > now + 15 * 60000) {
        return;
      }
    }

    const deduped = !shouldProcessOrderAlert(normalizedOrder);
    if (deduped && !isSocket) {
      return;
    }

    updateGlobalState({ newOrder: normalizedOrder });

    if (!isOrderMuted(normalizedOrder)) {
      // startGlobalAlertLoop already plays the sound immediately (and then loops),
      // so we must NOT play here as well — that caused the double sound.
      startGlobalAlertLoop(normalizedOrder);
    }

    const isTabHidden = typeof document !== 'undefined' && document.visibilityState === 'hidden';
    if (isTabHidden) {
      showBackgroundOrderNotification(normalizedOrder);
    }
  }, []);

  // Handle socket connection and listeners globally
  useEffect(() => {
    if (!API_BASE_URL || !String(API_BASE_URL).trim()) {
      updateGlobalState({ socketConnected: false });
      return;
    }
    if (!restaurantId) {
      return;
    }

    // Check if we need to initialize or update socket
    if (globalSocket && globalActiveRestaurantId === restaurantId) {
      return;
    }

    if (globalSocket) {
      globalSocket.disconnect();
      globalSocket = null;
      globalSocketConnected = false;
      updateGlobalState({ socketConnected: false });
    }

    globalActiveRestaurantId = restaurantId;

    let backendUrl = API_BASE_URL;
    try {
      const urlObj = new URL(backendUrl);
      let pathname = urlObj.pathname.replace(/^\/api\/?$/, '');
      backendUrl = `${urlObj.protocol}//${urlObj.hostname}${urlObj.port ? `:${urlObj.port}` : ''}${pathname}`;
    } catch (e) {
      backendUrl = backendUrl.replace(/\/api\/?$/, '').replace(/\/+$/, '');
      if (backendUrl.startsWith('https:') || backendUrl.startsWith('http:')) {
        const protocolMatch = backendUrl.match(/^(https?):/i);
        if (protocolMatch) {
          const protocol = protocolMatch[1].toLowerCase();
          const cleanPath = backendUrl.substring(protocol.length + 1).replace(/^\/+/, '');
          backendUrl = `${protocol}://${cleanPath}`;
        }
      }
    }
    backendUrl = backendUrl.replace(/^(https?):\/+/gi, '$1://').replace(/\/+$/, '');

    const frontendHostname = window.location.hostname;
    const isLocalhost = frontendHostname === 'localhost' || frontendHostname === '127.0.0.1' || frontendHostname === '';
    const isProductionBuild = globalThis.__ENV__.MODE === 'production' || globalThis.__ENV__.PROD;
    const isProductionDeployment = !isLocalhost && (window.location.protocol === 'https:' || frontendHostname.includes('.'));
    const backendIsLocalhost = backendUrl.includes('localhost') || backendUrl.includes('127.0.0.1');

    if (backendIsLocalhost && (isProductionBuild || isProductionDeployment) && !isLocalhost) {
      updateGlobalState({ socketConnected: false });
      return;
    }

    let socketOrigin = backendUrl;
    try {
      socketOrigin = new URL(backendUrl).origin;
    } catch {
      socketOrigin = String(backendUrl || "").replace(/\/api\/v\d+\/?$/i, "").replace(/\/api\/?$/i, "").replace(/\/+$/, "");
    }

    const socketUrl = `${socketOrigin}`;

    try {
      new URL(socketUrl);
    } catch {
      updateGlobalState({ socketConnected: false });
      return;
    }

    globalSocket = io(socketUrl, {
      path: '/socket.io/',
      transports: ['websocket', 'polling'],
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      reconnectionAttempts: Infinity,
      timeout: 20000,
      forceNew: false,
      autoConnect: true,
      auth: {
        token: localStorage.getItem('restaurant_accessToken') || localStorage.getItem('accessToken')
      }
    });

    globalSocket.on('connect', () => {
      globalSocketConnected = true;
      updateGlobalState({ socketConnected: true });
      globalSocket?.emit('join-restaurant', restaurantId);
    });

    globalSocket.on('connect_error', () => {
      globalSocketConnected = false;
      updateGlobalState({ socketConnected: false });
    });

    globalSocket.on('disconnect', (reason) => {
      globalSocketConnected = false;
      updateGlobalState({ socketConnected: false });
      if (reason === 'io server disconnect') {
        globalSocket?.connect();
      }
    });

    globalSocket.on('reconnect', () => {
      globalSocketConnected = true;
      updateGlobalState({ socketConnected: true });
      globalSocket?.emit('join-restaurant', restaurantId);
    });

    globalSocket.on('new_order', (orderData) => {
      const normalizedOrder = normalizeRestaurantOrderView({
        ...orderData,
        orderMongoId: orderData?.orderMongoId || orderData?._id || orderData?.order_id,
        orderId: orderData?.orderId || orderData?.order_id || orderData?._id,
      });
      updateGlobalState({ newOrder: normalizedOrder });
      handleIncomingOrderAlert(normalizedOrder, 'socket');
    });

    globalSocket.on('new_dining_booking', (bookingData) => {
      updateGlobalState({ newReservation: bookingData });
      startDiningAlertLoop(bookingData);
    });

    globalSocket.on('play_notification_sound', (data) => {
      const normalizedData = {
        orderId: data?.orderId || data?.order_id,
        orderMongoId: data?.orderMongoId || data?.order_meta_id || data?.order_mongo_id,
        ...data
      };
      handleIncomingOrderAlert(normalizedData, 'socket');
    });

    globalSocket.on('order_status_update', (data) => {
      if (typeof window !== 'undefined') {
        window.dispatchEvent(
          new CustomEvent('restaurantOrderStatusUpdate', {
            detail: data || {},
          }),
        );
      }
      const status = String(data?.orderStatus || data?.status || '').toLowerCase();

      // A Mongo ObjectId is a 24-char hex string — not a human order id, so don't show it.
      const isMongoId = (val) => /^[0-9a-fA-F]{24}$/.test(String(val || '').trim());
      const friendlyOrderId = (() => {
        const candidate = data?.orderId || data?.order_id || '';
        return candidate && !isMongoId(candidate) ? `#${candidate}` : '';
      })();

      // Order accepted — stop popup & sound immediately. Admin accept moves the
      // order straight to "preparing", so treat that (and the acceptedBy flag) as
      // accepted too, otherwise the restaurant popup would not dismiss.
      if (status === 'confirmed' || status === 'accepted' || status === 'preparing' || data?.acceptedBy === 'admin') {
        const orderId = data?.orderMongoId || data?._id || data?.orderId || data?.order_id;
        if (orderId) {
          const cleanId = String(orderId).trim();
          processedOrderIds.add(cleanId);
          globalMutedOrderIds.delete(cleanId);
        }
        stopGlobalAlertLoop();
        updateGlobalState({ newOrder: null, activeOrder: null, mutedOrderIds: new Set(globalMutedOrderIds) });
        // Toast only if admin accepted (not restaurant itself)
        if (data?.acceptedBy === 'admin') {
          toast.success(`Order ${friendlyOrderId} Accepted By Admin`, {
            duration: 6000,
            id: `admin-accepted-${data?.orderId || Date.now()}`
          });
        }
        dispatchNotificationInboxRefresh();
      }

      if (status === 'cancelled_by_admin') {
        toast.error(`Order ${friendlyOrderId} Rejected By Admin`, {
          duration: 6000,
          id: `admin-rejected-${data?.orderId || Date.now()}`
        });
        dispatchNotificationInboxRefresh();
      }

      if (status === 'delivered') {
        // Only announce a delivery for an order this restaurant actually tracked as
        // a real order (a valid display id). Guards against stray/stale events that
        // carry only a Mongo id firing a bogus "delivered" toast on new orders.
        if (friendlyOrderId) {
          toast.success(`Order ${friendlyOrderId} delivered successfully!`, {
            description: 'The order has been delivered to the customer.',
            duration: 6000,
            id: `delivered-${data?.orderId || Date.now()}`
          });
        }
        dispatchNotificationInboxRefresh();
      }
    });

    globalSocket.on('admin_notification', () => {
      dispatchNotificationInboxRefresh();
    });

    return () => {
      // Don't disconnect here to keep active room listeners alive across components
    };
  }, [restaurantId, handleIncomingOrderAlert]);

  // Handle REST polling fallback globally
  useEffect(() => {
    if (!restaurantId) return;
    if (globalPollingIntervalId) return;

    const ALERT_POLL_MS = 8000;

    const pollOrders = async () => {
      try {
        const token = localStorage.getItem('restaurant_accessToken') || localStorage.getItem('accessToken');
        const isAuthPage = getAppRoutePath().includes('/login') || getAppRoutePath().includes('/otp') || getAppRoutePath().includes('/signup');

        if (!token || isAuthPage) {
          if (globalActiveOrder) {
            globalActiveOrder = null;
            updateGlobalState({ activeOrder: null });
            stopGlobalAlertLoop();
          }
          return;
        }

        const response = await restaurantAPI.getOrders({ page: 1, limit: 30 });
        const rows = response?.data?.data?.orders || response?.data?.data?.data?.orders || [];

        const confirmed = (rows || [])
          .filter((o) => {
            // Only show alert for orders that are still pending/created (not yet accepted by admin).
            // Rows arrive normalized (backend "created" shows as status "confirmed"),
            // so read the raw backend status — checking `status` never matched, so
            // this poll saw "no pending orders" and stopped the ring within 8 s.
            const status = String(o?.orderStatus || o?.status || "").toLowerCase();
            if (status !== "created" && status !== "pending") return false;
            if (isProcessedOrder(o)) return false;

            if (o.scheduledAt) {
              const scheduledTime = new Date(o.scheduledAt).getTime();
              const now = Date.now();
              // Rings from 30 min before the slot until 30 min after it; a long-past scheduled order that was never
              // accepted must not ring every time the app is opened.
              return scheduledTime <= now + 30 * 60000 && scheduledTime >= now - 30 * 60000;
            }

            // Ignore stale test/bugged orders older than 30 minutes to prevent sound playing repeatedly on login
            const createdAt = new Date(o.createdAt || o.updatedAt || 0).getTime();
            if (!createdAt || Date.now() - createdAt > 30 * 60 * 1000) {
              return false;
            }

            return true;
          })
          .sort((a, b) => {
            const at = a?.updatedAt || a?.createdAt || 0;
            const bt = b?.updatedAt || b?.createdAt || 0;
            return new Date(bt).getTime() - new Date(at).getTime();
          });

        if (confirmed.length > 0) {
          confirmed.slice(0, 5).forEach((o) => {
            const orderId = o.orderMongoId || o.orderId || o._id || o.id;
            const currentOrderId = globalNewOrder?.orderMongoId || globalNewOrder?.orderId || globalNewOrder?._id || globalNewOrder?.id;
            if (String(orderId) !== String(currentOrderId)) {
              handleIncomingOrderAlert(o, 'poll');
            }
          });
        } else {
          // Nothing is waiting for the restaurant: once per app session tell the native shell to stop any order
          // ringtone left over from an earlier order, so opening the app never starts a ring on its own.
          if (!globalNativeRingCleared) {
            globalNativeRingCleared = true;
            void stopWebViewNativeNotification();
          }
          // If there are NO pending orders, ensure we clear any stale active order that might be playing sound
          if (globalActiveOrder) {
            globalActiveOrder = null;
            updateGlobalState({ activeOrder: null });
            stopGlobalAlertLoop();
          }
        }
      } catch (error) {
        // ignore
      }
    };

    pollOrders();
    globalPollingIntervalId = setInterval(pollOrders, ALERT_POLL_MS);

    const handleVisibility = () => {
      if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
        pollOrders();
      }
    };

    if (typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', handleVisibility);
    }

    return () => {
      // Polling remains alive globally
    };
  }, [restaurantId, handleIncomingOrderAlert]);

  // Request browser notification permission once on user interaction
  useEffect(() => {
    if (!supportsBrowserNotifications()) return;
    const askPermissionKey = 'restaurant_notification_permission_asked';
    if (Notification.permission !== 'default' || localStorage.getItem(askPermissionKey) === 'true') return;

    const requestPermissionOnce = async () => {
      localStorage.setItem(askPermissionKey, 'true');
      try {
        await Notification.requestPermission();
      } catch (error) {
        debugWarn('Failed to request restaurant notification permission:', error);
      }
    };

    const askOnInteraction = () => {
      requestPermissionOnce();
      window.removeEventListener('pointerdown', askOnInteraction);
      window.removeEventListener('keydown', askOnInteraction);
    };

    window.addEventListener('pointerdown', askOnInteraction, { once: true, passive: true });
    window.addEventListener('keydown', askOnInteraction, { once: true });

    return () => {
      window.removeEventListener('pointerdown', askOnInteraction);
      window.removeEventListener('keydown', askOnInteraction);
    };
  }, []);

  // Visibility change background browser notifications handler
  useEffect(() => {
    const onVisibilityChange = () => {
      if (typeof document === 'undefined') return;
      if (document.visibilityState === 'hidden' && globalActiveOrder && !globalIsMuted) {
        showBackgroundOrderNotification(globalActiveOrder);
      }
    };

    document.addEventListener('visibilitychange', onVisibilityChange);
    return () => {
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, []);

  // Track user interaction for audio unlocking
  useEffect(() => {
    const handleUserInteraction = async () => {
      if (typeof window === 'undefined') return;

      try {
        window.__userHasInteracted = true;

        // Unlock WebAudio silently
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (AudioCtx) {
          try {
            const ctx = new AudioCtx();
            if (ctx.state === 'suspended') {
              await ctx.resume();
            }
            const buf = ctx.createBuffer(1, 1, 22050);
            const srcNode = ctx.createBufferSource();
            srcNode.buffer = buf;
            srcNode.connect(ctx.destination);
            srcNode.start(0);
          } catch (_) {}
        }

        // Unlock HTML5 Audio element specifically for iOS WebKit using a tiny silent audio clip
        if (!globalAudio && typeof window !== 'undefined') {
          globalAudio = new Audio();
          globalAudio.preload = 'auto';
          globalAudio.volume = 1;
          // Silent MP3 base64 to safely unlock the Audio element without any "leaked" sound
          globalAudio.src = 'data:audio/mpeg;base64,';
        }
        if (globalAudio) {
          try {
            const p = globalAudio.play();
            if (p && typeof p.then === 'function') {
              p.then(() => {
                globalAudio.pause();
                globalAudio.currentTime = 0;
                // Once unlocked, switch to the actual alert sound so it's ready
                preloadAudio().then(src => {
                  if (globalAudio) globalAudio.src = src;
                });
              }).catch(() => {
                // If it failed to play, still try to load the actual source
                preloadAudio().then(src => {
                  if (globalAudio) globalAudio.src = src;
                });
              });
            }
          } catch (_) {}
        }

        // If there's an active order pending that isn't muted, resume the alarm immediately!
        if (globalActiveOrder && !globalIsMuted && !isOrderMuted(globalActiveOrder)) {
          playGlobalNotificationSound(globalActiveOrder);
          startGlobalAlertLoop(globalActiveOrder);
        }
      } catch (error) {
        // ignore
      }

      document.removeEventListener('click', handleUserInteraction);
      document.removeEventListener('touchstart', handleUserInteraction);
      document.removeEventListener('keydown', handleUserInteraction);
      window.removeEventListener('pointerdown', handleUserInteraction);
    };

    document.addEventListener('click', handleUserInteraction, { once: true });
    document.addEventListener('touchstart', handleUserInteraction, { once: true });
    document.addEventListener('keydown', handleUserInteraction, { once: true });
    window.addEventListener('pointerdown', handleUserInteraction, { once: true, passive: true });

    return () => {
      document.removeEventListener('click', handleUserInteraction);
      document.removeEventListener('touchstart', handleUserInteraction);
      document.removeEventListener('keydown', handleUserInteraction);
      window.removeEventListener('pointerdown', handleUserInteraction);
    };
  }, []);

  const setMuted = useCallback((nextMuted) => {
    const muted = Boolean(nextMuted);
    updateGlobalState({ isMuted: muted });
    if (muted) {
      stopGlobalAlertLoop();
    } else if (globalActiveOrder) {
      playGlobalNotificationSound(globalActiveOrder);
      startGlobalAlertLoop(globalActiveOrder);
    }
  }, []);

  const clearNewOrder = useCallback((orderOrId) => {
    let targetId = null;
    if (orderOrId) {
      if (typeof orderOrId === 'object') {
        const ids = [
          orderOrId.orderMongoId,
          orderOrId.orderId,
          orderOrId._id,
          orderOrId.id,
          orderOrId.mongoId,
          orderOrId.order_id,
          orderOrId.order_mongo_id
        ].filter(Boolean);
        ids.forEach(id => {
          const cleanId = String(id).trim();
          processedOrderIds.add(cleanId);
          globalMutedOrderIds.delete(cleanId);
        });
        targetId = getOrderAlertKey(orderOrId);
      } else {
        targetId = String(orderOrId).trim();
        processedOrderIds.add(targetId);
        globalMutedOrderIds.delete(targetId);
      }
      saveProcessedOrderIds();
      saveMutedOrderIds();
    }
    stopGlobalAlertLoop();
    updateGlobalState({ newOrder: null, activeOrder: null, mutedOrderIds: new Set(globalMutedOrderIds) });
  }, []);

  const muteOrders = useCallback((orderIds) => {
    if (!Array.isArray(orderIds)) return;
    orderIds.forEach(id => {
      if (id) globalMutedOrderIds.add(String(id).trim());
    });
    saveMutedOrderIds();

    // Stop alarm loop if active order is among the muted ones
    if (globalActiveOrder && isOrderMuted(globalActiveOrder)) {
      stopGlobalAlertLoop();
    }

    updateGlobalState({ mutedOrderIds: new Set(globalMutedOrderIds) });
  }, []);

  const unmuteOrder = useCallback((orderId) => {
    if (!orderId) return;
    const cleanId = String(orderId).trim();
    globalMutedOrderIds.delete(cleanId);
    saveMutedOrderIds();

    // Restart the alert for the active order once it is no longer muted.
    if (globalActiveOrder && !isOrderMuted(globalActiveOrder)) {
      startGlobalAlertLoop(globalActiveOrder);
    }

    updateGlobalState({ mutedOrderIds: new Set(globalMutedOrderIds) });
  }, []);

  const clearNewReservation = useCallback(() => {
    stopDiningAlertLoop();
    stopWebViewNativeNotification();
    updateGlobalState({ newReservation: null });
  }, []);

  return {
    newOrder: localState.newOrder,
    newReservation: localState.newReservation,
    clearNewOrder,
    clearNewReservation,
    isConnected: localState.isConnected,
    isMuted: localState.isMuted,
    setMuted,
    playNotificationSound: playGlobalNotificationSound,
    stopSound: stopGlobalAlertLoop,
    startAlertLoop: startGlobalAlertLoop,
    mutedOrderIds: localState.mutedOrderIds || new Set(),
    muteOrders,
    unmuteOrder,
  };
};

import { useEffect, useRef, useState } from 'react';
import io from 'socket.io-client';
import { toast } from '@/lib/toast';
import { API_BASE_URL } from '@food/api/config';
import { userAPI } from '@food/api';
import { dispatchNotificationInboxRefresh } from '@food/hooks/useNotificationInbox';
import { isModuleAuthenticated } from '@food/utils/auth';

const debugLog = (...args) => {
  if (globalThis.__ENV__.DEV) {
    console.log('📬 [UserSocket]', ...args);
  }
};

/**
 * Hook for user to receive real-time order notifications.
 * Dispatches 'orderStatusNotification' custom event for OrderTrackingCard.
 */
export const useUserNotifications = () => {
  const socketRef = useRef(null);
  const [isConnected, setIsConnected] = useState(false);
  const [userId, setUserId] = useState(null);
  const lastDropOtpToastRef = useRef({ key: '', at: 0 });
  const lastOrderStatusToastRef = useRef({ key: '', at: 0 });

  const DROP_OTP_TOAST_ID = 'user-delivery-drop-otp';
  const DROP_OTP_DEDUPE_MS = 15000;
  const ORDER_STATUS_TOAST_ID = 'user-order-status-update';
  const ORDER_STATUS_DEDUPE_MS = 4000;

  // Fetch current user ID
  useEffect(() => {
    if (!isModuleAuthenticated('user')) {
      return;
    }
    const fetchUserId = async () => {
      try {
        const response = await userAPI.getProfile();
        if (response.data?.success && response.data.data?.user) {
          const user = response.data.data.user;
          const id = user._id?.toString() || user.userId || user.id;
          setUserId(id);
        }
      } catch (error) {
        // Not logged in or error
      }
    };
    fetchUserId();
  }, []);

  useEffect(() => {
    if (!API_BASE_URL || !String(API_BASE_URL).trim()) {
      setIsConnected(false);
      return;
    }
    if (!userId) {
      return;
    }

    // Normalize backend URL
    let backendUrl = API_BASE_URL;
    try {
      backendUrl = new URL(backendUrl).origin;
    } catch {
      backendUrl = String(backendUrl || "")
        .replace(/\/api\/v\d+\/?$/i, "")
        .replace(/\/api\/?$/i, "")
        .replace(/\/+$/, "");
    }

    const socketUrl = `${backendUrl}`;

    // Auth token
    const token = localStorage.getItem('user_accessToken') || localStorage.getItem('accessToken');
    if (!token) return;

    debugLog('🔌 Connecting to User Socket.IO:', socketUrl);

    socketRef.current = io(socketUrl, {
      path: '/socket.io/',
      transports: ['websocket', 'polling'],
      reconnection: true,
      auth: { token },
      forceNew: false,
      multiplex: true
    });

    socketRef.current.on('connect', () => {
      debugLog('✅ User Socket connected, userId:', userId);
      setIsConnected(true);
      if (typeof window !== 'undefined') {
        window.orderSocketConnected = true;
        window.dispatchEvent(new CustomEvent('userSocketConnectionChange', { detail: { isConnected: true } }));
      }
      // Backend auto-joins 'user:userId' room based on role/token in config/socket.js
    });

    socketRef.current.on('order_status_update', (data) => {
      debugLog('🔔 Order status update received:', data);

      const rawId = String(data.displayOrderId || data.orderDisplayId || data.orderId || '');
      const readableId = rawId.length > 20
        ? `FOD-${rawId.slice(-6).toUpperCase()}`
        : rawId || 'Update';

      const rawTitle = String(data.title || '');
      const title = (rawTitle && (!data.orderId || !rawTitle.includes(data.orderId) || String(data.orderId).length <= 20))
        ? rawTitle
        : `Order #${readableId}`;
      const message = data.message || `Your order status is now ${String(data.orderStatus || '').replace(/_/g, ' ')}`;

      const isImportant = String(data.orderStatus).includes('cancel') ||
        ['ready_for_pickup', 'ready', 'confirmed', 'delivered', 'out_for_delivery'].includes(data.orderStatus);

      const statusKey = `${readableId}:${String(data.orderStatus || '')}`;
      const now = Date.now();
      const isDuplicateStatusToast =
        statusKey &&
        statusKey === lastOrderStatusToastRef.current.key &&
        now - lastOrderStatusToastRef.current.at < ORDER_STATUS_DEDUPE_MS;

      if (isImportant && !isDuplicateStatusToast) {
        lastOrderStatusToastRef.current = { key: statusKey, at: now };
        window.dispatchEvent(new CustomEvent('show-user-notification-toast', {
          detail: { title, message }
        }));
        // Only refresh inbox (bell count) for delivered orders
        if (data.orderStatus === 'delivered') {
          dispatchNotificationInboxRefresh();
        }
      }

      // Dispatch custom event for OrderTrackingCard and other listeners
      const event = new CustomEvent('orderStatusNotification', {
        detail: {
          orderMongoId: data.orderMongoId,
          orderId: readableId,
          status: data.orderStatus,
          orderStatus: data.orderStatus, // Ensure compatibility with different UI checks
          title,
          message,
          deliveryState: data.deliveryState,
          deliveryVerification: data.deliveryVerification,
          timestamp: new Date().toISOString()
        }
      });
      window.dispatchEvent(event);
    });

    /** Customer receives handover OTP when partner confirms "reached drop" (never shown to partner). */
    socketRef.current.on('delivery_drop_otp', (payload) => {
      debugLog('🔐 Delivery handover OTP:', payload?.orderId);
      const otp = payload?.otp != null ? String(payload.otp) : '';
      const orderId = payload?.orderId != null ? String(payload.orderId) : '';
      const message = payload?.message != null ? String(payload.message) : '';

      const otpKey = `${orderId}:${otp}`;
      const now = Date.now();
      const lastToast = lastDropOtpToastRef.current;
      const isDuplicateOtp =
        otpKey &&
        otpKey === lastToast.key &&
        now - lastToast.at < DROP_OTP_DEDUPE_MS;

      if (isDuplicateOtp) {
        return;
      }

      lastDropOtpToastRef.current = { key: otpKey, at: now };

      window.dispatchEvent(
        new CustomEvent('deliveryDropOtp', {
          detail: {
            orderMongoId: payload?.orderMongoId,
            orderId,
            otp,
            message,
            orderType: payload?.orderType || 'delivery'
          }
        })
      );
      const isTakeaway = payload?.orderType === 'takeaway';
      const title = orderId 
        ? `Order #${orderId} — ${isTakeaway ? 'Takeaway OTP' : 'Delivery OTP'}` 
        : (isTakeaway ? 'Takeaway OTP' : 'Delivery OTP');
      const parts = [message, otp ? `OTP: ${otp}` : ''].filter(Boolean);

      toast.dismiss(DROP_OTP_TOAST_ID);
      toast.message(title, {
        id: DROP_OTP_TOAST_ID,
        description: parts.join(' — ') || (isTakeaway ? 'Verification OTP for your takeaway pickup.' : 'Handover OTP from your delivery partner.'),
        duration: 12_000
      });
    });

    socketRef.current.on('dining_booking_update', (payload) => {
      debugLog('🍽️ Dining booking update:', payload);
      window.dispatchEvent(new CustomEvent('diningBookingStatusUpdate', { detail: payload }));
    });

    socketRef.current.on('admin_notification', (payload) => {
      window.dispatchEvent(new CustomEvent('show-user-notification-toast', {
        detail: {
          title: payload?.title || 'Notification',
          message: payload?.message || '',
        }
      }));
      dispatchNotificationInboxRefresh();
    });

    socketRef.current.on('connect_error', () => {
      if (globalThis.__ENV__.DEV) {
        // debugLog('❌ Socket connection error');
      }
      setIsConnected(false);
      if (typeof window !== 'undefined') {
        window.orderSocketConnected = false;
        window.dispatchEvent(new CustomEvent('userSocketConnectionChange', { detail: { isConnected: false } }));
      }
    });

    socketRef.current.on('disconnect', (reason) => {
      debugLog('🔌 Socket disconnected:', reason);
      setIsConnected(false);
      if (typeof window !== 'undefined') {
        window.orderSocketConnected = false;
        window.dispatchEvent(new CustomEvent('userSocketConnectionChange', { detail: { isConnected: false } }));
      }
    });

    return () => {
      if (socketRef.current) {
        socketRef.current.disconnect();
        socketRef.current = null;
      }
    };
  }, [userId]);

  return { isConnected };
};

// Native voice search: same hook API and messages as the web (which used the browser SpeechRecognition inside the
// Flutter WebView). Speech comes from @/lib/voice (expo-speech-recognition); interim text, the 2 s silence commit and
// the two automatic retries on "no speech" are kept.
import { useState, useCallback, useRef, useEffect } from 'react';
import { toast } from '@/lib/toast';
import { isVoiceSearchAvailable, startVoiceSearch, stopVoiceSearch } from '@/lib/voice';

const MAX_AUTO_RETRIES = 2;
// commit this long after the last word when the recognizer has not sent its final result yet (was 2 s: felt slow)
const SILENCE_COMMIT_MS = 1000;

const WEBVIEW_MIC_DENIED_MESSAGE =
    'Microphone access denied. Enable microphone for this app in phone settings, then try again.';

export const useVoiceSearch = (onResult, onError) => {
    const [isListening, setIsListening] = useState(false);
    const [transcript, setTranscript] = useState('');
    const [error, setError] = useState(null);

    const isStartingRef = useRef(false);
    const silenceTimeoutRef = useRef(null);
    const latestTranscriptRef = useRef('');
    const hasCommittedRef = useRef(false);
    const retryCountRef = useRef(0);
    const shouldKeepListeningRef = useRef(false);
    const sessionRef = useRef(0);
    const mountedRef = useRef(true);

    const onResultRef = useRef(onResult);
    onResultRef.current = onResult;

    const onErrorRef = useRef(onError);
    onErrorRef.current = onError;

    const isListeningRef = useRef(false);
    isListeningRef.current = isListening;

    useEffect(() => {
        mountedRef.current = true;
        return () => {
            mountedRef.current = false;
            if (silenceTimeoutRef.current) clearTimeout(silenceTimeoutRef.current);
            if (shouldKeepListeningRef.current) {
                shouldKeepListeningRef.current = false;
                stopVoiceSearch();
            }
        };
    }, []);

    const clearSilenceTimeout = () => {
        if (silenceTimeoutRef.current) {
            clearTimeout(silenceTimeoutRef.current);
            silenceTimeoutRef.current = null;
        }
    };

    const teardownRecognition = useCallback(() => {
        clearSilenceTimeout();
        sessionRef.current += 1;
        stopVoiceSearch();
    }, []);

    const stopListening = useCallback(() => {
        shouldKeepListeningRef.current = false;
        teardownRecognition();
        if (mountedRef.current) setIsListening(false);
        isStartingRef.current = false;
    }, [teardownRecognition]);

    const commitResult = useCallback(() => {
        if (hasCommittedRef.current) {
            return;
        }

        const finalResult = latestTranscriptRef.current.trim();
        if (!finalResult) {
            return;
        }

        hasCommittedRef.current = true;
        shouldKeepListeningRef.current = false;
        onResultRef.current?.(finalResult);
        stopListening();
    }, [stopListening]);

    const scheduleSilenceCommit = useCallback(() => {
        clearSilenceTimeout();
        silenceTimeoutRef.current = setTimeout(() => {
            if (latestTranscriptRef.current.trim()) {
                commitResult();
            }
        }, SILENCE_COMMIT_MS);
    }, [commitResult]);

    const failWith = useCallback((message, code) => {
        setError(message);
        toast.error(message, { duration: 3000 });
        onErrorRef.current?.(code);
        stopListening();
    }, [stopListening]);

    // One recognition run (the web created a new SpeechRecognition per run as well).
    const runRecognition = useCallback(() => {
        const session = ++sessionRef.current;
        const isCurrent = () => session === sessionRef.current && mountedRef.current;

        setIsListening(true);
        setError(null);
        isStartingRef.current = false;

        startVoiceSearch({
            lang: 'en-IN',
            onPartial: (text) => {
                if (!isCurrent()) return;
                const currentText = String(text || '').trim();
                if (!currentText) return;
                latestTranscriptRef.current = currentText;
                setTranscript(currentText);
                setError(null);
                scheduleSilenceCommit();
            },
        })
            .then((finalText) => {
                if (!isCurrent()) return;
                const currentText = String(finalText || '').trim();
                if (currentText) {
                    latestTranscriptRef.current = currentText;
                    setTranscript(currentText);
                    commitResult();
                    return;
                }

                // Recognition ended without a final result (the web's onend).
                if (hasCommittedRef.current || !shouldKeepListeningRef.current) {
                    setIsListening(false);
                    isStartingRef.current = false;
                    return;
                }

                if (latestTranscriptRef.current.trim()) {
                    commitResult();
                    return;
                }

                if (retryCountRef.current < MAX_AUTO_RETRIES) {
                    retryCountRef.current += 1;
                    isStartingRef.current = false;
                    setIsListening(false);
                    setTimeout(() => {
                        if (!shouldKeepListeningRef.current || hasCommittedRef.current || !mountedRef.current) {
                            return;
                        }
                        try {
                            isStartingRef.current = true;
                            runRecognition();
                        } catch (restartError) {
                            console.error('Speech recognition restart failed:', restartError);
                            setError('Could not keep listening. Please try again.');
                            stopListening();
                        }
                    }, 250);
                    return;
                }

                setError('No speech detected. Tap try again and speak clearly.');
                setIsListening(false);
                isStartingRef.current = false;
            })
            .catch((err) => {
                if (!isCurrent()) return;
                const code = String(err?.code || err?.message || '').toLowerCase();
                console.error('Speech recognition error:', code);

                if (code.includes('aborted')) {
                    return;
                }
                if (code.includes('permission') || code.includes('not-allowed') || code.includes('denied')) {
                    failWith(WEBVIEW_MIC_DENIED_MESSAGE, 'not-allowed');
                    return;
                }
                if (code.includes('network')) {
                    failWith('Network error during voice search.', 'network');
                    return;
                }
                setError('Could not keep listening. Please try again.');
                stopListening();
            });
        // runRecognition calls itself for the retries
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [commitResult, scheduleSilenceCommit, stopListening, failWith]);

    const startListening = useCallback(async () => {
        if (isListeningRef.current || isStartingRef.current) {
            return;
        }

        const available = await isVoiceSearchAvailable();
        if (!available) {
            const message = 'Voice search is not supported in this browser.';
            setError(message);
            toast.error(message);
            onErrorRef.current?.('unsupported');
            return;
        }

        try {
            isStartingRef.current = true;
            shouldKeepListeningRef.current = true;
            hasCommittedRef.current = false;
            retryCountRef.current = 0;
            latestTranscriptRef.current = '';
            setTranscript('');
            setError(null);

            teardownRecognition();
            runRecognition();
        } catch (startError) {
            isStartingRef.current = false;
            shouldKeepListeningRef.current = false;
            console.error('Speech recognition initialization failed:', startError);
            const message = 'Could not start voice search. Please try again.';
            setError(message);
            toast.error(message, { duration: 3000 });
        }
    }, [runRecognition, teardownRecognition]);

    const clearError = useCallback(() => {
        setError(null);
    }, []);

    return {
        isListening,
        transcript,
        error,
        startListening,
        stopListening,
        clearError,
    };
};

import { useState, useEffect, useCallback, useRef } from 'react'
import { zoneAPI } from '@food/api'
const debugLog = (...args) => {}
const debugWarn = (...args) => {}
const debugError = (...args) => {}

// ---- Cross-hook caching & in-flight de-dupe (module-level) ----
// Multiple screens/components call useZone(location). Without shared caching,
// we spam /food/zones/detect with the same coords.
const ZONE_CACHE_TTL_MS = 30 * 1000
const zoneCache = new Map() // key -> { ts, payload }
const zoneInFlight = new Map() // key -> Promise<payload>

const roundCoord = (v, digits = 5) => {
  const n = Number(v)
  if (!Number.isFinite(n)) return null
  const p = 10 ** digits
  return Math.round(n * p) / p
}

const zoneKeyFromCoords = (lat, lng) => {
  const rLat = roundCoord(lat, 5)
  const rLng = roundCoord(lng, 5)
  if (rLat === null || rLng === null) return null
  return `${rLat},${rLng}`
}

/** Remembers a /food/zones/detect answer the way the app reads it back on its next start. */
export const storeZonePayload = (data) => {
  if (data?.status === 'IN_SERVICE' && data.zoneId) {
    localStorage.setItem('userZoneId', data.zoneId)
    localStorage.setItem('userZone', JSON.stringify(data.zone))
    localStorage.setItem('userZoneStatus', 'IN_SERVICE')
  } else {
    localStorage.removeItem('userZoneId')
    localStorage.removeItem('userZone')
    localStorage.setItem('userZoneStatus', 'OUT_OF_SERVICE')
  }
}

const applyZonePayload = (data, { setZoneId, setZone, setZoneStatus }) => {
  if (data?.status === 'IN_SERVICE' && data.zoneId) {
    setZoneId(data.zoneId)
    setZone(data.zone || null)
    setZoneStatus('IN_SERVICE')
  } else {
    setZoneId(null)
    setZone(null)
    setZoneStatus('OUT_OF_SERVICE')
  }
  storeZonePayload(data)
}


/**
 * Hook to detect and manage user's zone based on location
 * Automatically detects zone when location is available
 */
export function useZone(location) {
  const [zoneId, setZoneId] = useState(() => localStorage.getItem("userZoneId"))
  const [zoneStatus, setZoneStatus] = useState(() => localStorage.getItem("userZoneStatus") || "loading")
  const [zone, setZone] = useState(() => {
    try {
      const cached = localStorage.getItem("userZone")
      return cached ? JSON.parse(cached) : null
    } catch { return null }
  })
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  
  const initialLat = roundCoord(location?.latitude, 5)
  const initialLng = roundCoord(location?.longitude, 5)
  const prevCoordsRef = useRef({ latitude: null, longitude: null })
  const debounceTimerRef = useRef(null)

  // Detect zone when location is available
  const detectZone = useCallback(async (lat, lng) => {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
      setZoneStatus("OUT_OF_SERVICE");
      setZoneId(null);
      setZone(null);
      return;
    }

    try {
      setLoading(true)
      setError(null)

      const key = zoneKeyFromCoords(lat, lng)
      const now = Date.now()
      if (key) {
        const cached = zoneCache.get(key)
        if (cached && now - cached.ts < ZONE_CACHE_TTL_MS) {
          applyZonePayload(cached.payload, { setZoneId, setZone, setZoneStatus })
          return
        }
      }

      const promise = (() => {
        if (key && zoneInFlight.has(key)) return zoneInFlight.get(key)
        const p = zoneAPI
          .detectZone(lat, lng)
          .then((response) => {
            if (!response?.data?.success) {
              throw new Error(response?.data?.message || 'Failed to detect zone')
            }
            return response.data.data
          })
          .finally(() => {
            if (key) zoneInFlight.delete(key)
          })
        if (key) zoneInFlight.set(key, p)
        return p
      })()

      const data = await promise
      if (key) zoneCache.set(key, { ts: now, payload: data })
      applyZonePayload(data, { setZoneId, setZone, setZoneStatus })
    } catch (err) {
      debugError("Error detecting zone:", err);
      setError(
        err.response?.data?.message || err.message || "Failed to detect zone",
      );

      // Try to use cached zone if available
      const cachedZoneId = localStorage.getItem("userZoneId");
      if (cachedZoneId) {
        const cachedZone = localStorage.getItem("userZone");
        setZoneId(cachedZoneId);
        setZone(cachedZone ? JSON.parse(cachedZone) : null);
        setZoneStatus("IN_SERVICE");
      } else {
        // Network/CORS/backend failures should not be treated as confirmed out-of-zone.
        setZoneStatus("loading");
        setZoneId(null);
        setZone(null);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  const lat = roundCoord(location?.latitude, 5)
  const lng = roundCoord(location?.longitude, 5)

  // Auto-detect zone when location changes. Keyed on the rounded coords: the
  // raw ones used to re-run this when they changed without changing the
  // rounded value (e.g. "22.7533" -> 22.7533), which cancelled the pending
  // detect below and never rescheduled it — loading stayed true and the whole
  // user app sat on the skeleton.
  useEffect(() => {

    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      // Only detect zone if coordinates changed significantly (~1m via 5 decimals)
      const coordsChanged =
        prevCoordsRef.current.latitude !== lat ||
        prevCoordsRef.current.longitude !== lng
      if (coordsChanged) {
        const hadCachedZone = Boolean(
          typeof localStorage !== "undefined" && localStorage.getItem("userZoneId"),
        );
        // Keep cached zone usable for instant restaurant fetch on refresh;
        // only block UI when we have no zone at all yet.
        if (!hadCachedZone) setLoading(true);
        prevCoordsRef.current = { latitude: lat, longitude: lng }
        if (debounceTimerRef.current) {
          clearTimeout(debounceTimerRef.current)
        }
        debounceTimerRef.current = setTimeout(() => {
          debounceTimerRef.current = null
          detectZone(lat, lng)
        }, 50)
      }
    } else {
      // Try to use cached zone if location not available
      const cachedZoneId = localStorage.getItem("userZoneId");
      if (cachedZoneId) {
        const cachedZone = localStorage.getItem("userZone");
        const cachedStatus = localStorage.getItem("userZoneStatus");
        setZoneId(cachedZoneId);
        setZone(cachedZone ? JSON.parse(cachedZone) : null);
        setZoneStatus(cachedStatus || "IN_SERVICE");
      } else {
        setZoneStatus("loading"); // Default to loading instead of OUT_OF_SERVICE if location not yet fetched
        setZoneId(null);
        setZone(null);
      }
    }
    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current)
        debounceTimerRef.current = null
        // Detect never ran for these coords (StrictMode remount / unmount):
        // forget them so the next run starts it again.
        prevCoordsRef.current = { latitude: null, longitude: null }
      }
    }
  }, [lat, lng, detectZone])

  // Manual refresh zone
  const refreshZone = useCallback(() => {
    const lat = location?.latitude;
    const lng = location?.longitude;
    if (Number.isFinite(lat) && Number.isFinite(lng)) {
      detectZone(lat, lng);
    }
  }, [location?.latitude, location?.longitude, detectZone]);

  return {
    zoneId,
    zone,
    zoneStatus,
    // Don't OR with coordsChanged — that re-flashes loading on every parent re-render
    // until the effect commits, which makes Home look like it "auto-refreshes".
    loading,
    error,
    isInService: zoneStatus === "IN_SERVICE",
    isOutOfService: zoneStatus === "OUT_OF_SERVICE",
    refreshZone,
  };
}

