                          <View style={[s.catCircle, pressed && { transform: [{ scale: 0.95 }] }]}>
                            {/* Shining Glint Effect */}
                            <Glint width={80} duration={2000} repeatDelay={3000 + index * 500} via={0.4} />
                            <OptimizedImage
                              src={category.image}
                              alt={category.name}
                              style={{ width: "100%", height: "100%" }}
