        return
      }
      let settled = false
      const finish = () => {
        if (settled) return
        settled = true
        resolve()
      }
      const timeoutId = setTimeout(finish, 500)
      ExpoImage.prefetch(resolved.uri, "memory-disk")
        .catch(() => {})
        .finally(() => {
          clearTimeout(timeoutId)
          finish()
        })
    })

