/**
 * Clear all authentication data for all modules
 */
export function clearAuthData() {
  const modules = ['admin', 'restaurant', 'delivery', 'user'];
  modules.forEach(module => {
    clearModuleAuth(module);
  });
  // Also clear legacy token if it exists
  localStorage.removeItem('accessToken');
  localStorage.removeItem('user');
}

/**
 * Set authentication data for a specific module
 * @param {string} module - Module name (admin, restaurant, delivery, user)
 * @param {string} token - Access token
 * @param {Object} user - User data
 * @param {string|null} refreshToken - Optional refresh token
 * @throws {Error} If localStorage is not available or quota exceeded
 */
export function setAuthData(module, token, user, refreshToken = null) {
  if (module === 'user') prepareForSignIn(user);
  try {
    // Check if localStorage is available
    if (typeof Storage === 'undefined' || !localStorage) {
      throw new Error('localStorage is not available');
    }

    // Validate inputs
    if (!module || !token) {
      throw new Error(`Invalid parameters: module=${module}, token=${!!token}`);
    }

    console.log(`[setAuthData] Storing auth for module: ${module}`, {
      hasToken: !!token,
      tokenLength: token?.length,
      hasUser: !!user
    });

    // Store module-specific token (don't clear other modules)
    const tokenKey = `${module}_accessToken`;
    const refreshTokenKey = `${module}_refreshToken`;
    const authKey = `${module}_authenticated`;
    const userKey = `${module}_user`;

    // Prevent stale profile data from previous accounts after re-login.
    if (module === "user") {
      clearUserSession();
    } else if (module === "restaurant") {
      clearRestaurantSessionCache();
    }

    localStorage.setItem(tokenKey, token);
    if (refreshToken && typeof refreshToken === "string") {
      localStorage.setItem(refreshTokenKey, refreshToken);
    }
    localStorage.setItem(authKey, 'true');

    if (module === "user") {
      localStorage.setItem("userToken", token);
      localStorage.setItem("token", token);
      localStorage.setItem("role", "user");
      localStorage.setItem("chatRole", "user");
    }

    if (user) {
      try {
        localStorage.setItem(userKey, JSON.stringify(user));
        if (module === "user") {
          localStorage.setItem("userInfo", JSON.stringify(user));
        }
      } catch (userError) {
        console.warn('Failed to store user data, but token was stored:', userError);
      }
    }

    // Verify the token was stored correctly
    const storedToken = localStorage.getItem(tokenKey);
    const storedAuth = localStorage.getItem(authKey);
    
    if (storedToken !== token) {
      console.error(`[setAuthData] Token mismatch:`, {
        expected: token?.substring(0, 20) + '...',
        stored: storedToken?.substring(0, 20) + '...'
      });
      throw new Error(`Token storage verification failed for module: ${module}`);
    }

    if (storedAuth !== 'true') {
      console.error(`[setAuthData] Auth flag mismatch:`, {
        expected: 'true',
        stored: storedAuth
      });
      throw new Error(`Authentication flag storage failed for module: ${module}`);
    }

    console.log(`[setAuthData] Successfully stored auth data for ${module}`);
  } catch (error) {
    // If quota exceeded, try to clear some space
    if (error.name === 'QuotaExceededError' || error.code === 22) {
      console.warn('localStorage quota exceeded. Attempting to clear old data...');
      // Clear legacy tokens
      try {
        localStorage.removeItem('accessToken');
        localStorage.removeItem('user');
        // Retry storing
        localStorage.setItem(`${module}_accessToken`, token);
        if (refreshToken && typeof refreshToken === "string") {
          localStorage.setItem(`${module}_refreshToken`, refreshToken);
        }
        localStorage.setItem(`${module}_authenticated`, 'true');
        if (user) {
          localStorage.setItem(`${module}_user`, JSON.stringify(user));
        }
        
        // Verify again after retry
        const storedToken = localStorage.getItem(`${module}_accessToken`);
        if (storedToken !== token) {
          throw new Error('Token storage failed even after clearing space');
        }
      } catch (retryError) {
        console.error('Failed to store auth data after clearing space:', retryError);
        throw new Error('Unable to store authentication data. Please clear browser storage and try again.');
      }
    } else {
      console.error('[setAuthData] Error storing auth data:', error);
      throw error;
    }
  }
}

export function setUnifiedAuthData(data) {
  if (!data) return;

  const foodToken = data.accessToken || data.foodAuth?.accessToken;
  const foodUser = data.user || data.foodAuth?.user;
  const foodRefreshToken = data.refreshToken || data.foodAuth?.refreshToken;
  if (foodToken && foodUser) {
    setAuthData("user", foodToken, foodUser, foodRefreshToken);
  }

  const taxiAuth = data.taxiAuth;
  if (taxiAuth && taxiAuth.token && taxiAuth.user) {
    localStorage.setItem("userToken", taxiAuth.token);
    localStorage.setItem("token", taxiAuth.token);
    localStorage.setItem("userInfo", JSON.stringify(taxiAuth.user));
    localStorage.setItem("role", "user");
    localStorage.setItem("chatRole", "user");
    return;
  }

  if (foodToken && foodUser) {
    localStorage.setItem("userToken", foodToken);
    localStorage.setItem("token", foodToken);
    localStorage.setItem("userInfo", JSON.stringify(foodUser));
    localStorage.setItem("role", "user");
    localStorage.setItem("chatRole", "user");
  }
}

export function isUnifiedAuthenticated() {
  const foodToken = localStorage.getItem("user_accessToken");
  const taxiToken = localStorage.getItem("userToken");
  return !!(foodToken && taxiToken);
}

/**
 * Pending-approval ticket (restaurant / delivery). Given by the backend after
 * OTP while the account is not approved yet; the "under review" screen polls
 * with it and receives a login session as soon as admin approves.
 */
const pendingTicketKey = (module) => `${module}_pending_ticket`

export function setPendingTicket(module, ticket) {
  try {
    if (ticket) localStorage.setItem(pendingTicketKey(module), String(ticket))
  } catch {
    // ignore
  }
}

export function getPendingTicket(module) {
  try {
    return localStorage.getItem(pendingTicketKey(module)) || ""
  } catch {
    return ""
  }
}

export function clearPendingTicket(module) {
  try {
    localStorage.removeItem(pendingTicketKey(module))
  } catch {
    // ignore
  }
}

/**
 * Business Settings Utility
 * Handles loading and updating business settings (favicon, title, logo)
 */

import apiClient from "@food/api/axios";
import { API_ENDPOINTS } from "@food/api/config";
import { publicGetOnce } from "@food/api";

const SETTINGS_KEY = 'helloparth_business_settings';

// Initialize from localStorage immediately so it's available for components on mount
let cachedSettings = (() => {
  try {
    const saved = localStorage.getItem(SETTINGS_KEY);
    return saved ? JSON.parse(saved) : null;
  } catch (e) {
    return null;
  }
})();

// Apply cached settings immediately on module load if they exist
if (cachedSettings) {
  setTimeout(() => {
    updateFavicon(cachedSettings.favicon?.url);
    updateTitle(cachedSettings.companyName);
  }, 0);
}

let inFlightSettingsPromise = null;

/**
 * Load business settings from backend (public endpoint - no auth required)
 */
export const loadBusinessSettings = async () => {
  try {
    // If we have no cached settings, we MUST fetch
    // If we have cached settings, we still try to fetch in background to ensure they are fresh
    const endpoint = API_ENDPOINTS.ADMIN.BUSINESS_SETTINGS_PUBLIC;
    if (!endpoint || (typeof endpoint === "string" && !endpoint.trim())) {
      return cachedSettings;
    }

    if (inFlightSettingsPromise) {
      return await inFlightSettingsPromise;
    }

    inFlightSettingsPromise = (async () => {
      // Use public endpoint that doesn't require authentication
      // Use noCache to ensure we get fresh data from server this time
      const response = await publicGetOnce(endpoint, { noCache: true });
      const settings = response?.data?.data || response?.data;

      if (settings) {
        cachedSettings = settings;
        try {
          localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
        } catch (e) {}

        updateFavicon(settings.favicon?.url);
        updateTitle(settings.companyName);
        return settings;
      }
      return cachedSettings;
    })();

    return await inFlightSettingsPromise;
  } catch (error) {
    // Return cached if failed
    return cachedSettings;
  } finally {
    inFlightSettingsPromise = null;
  }
};

/**
 * Update favicon in document
 */
export const updateFavicon = (url) => {
  // Native app: there is no browser tab icon (the launcher icon is part of the app build).
  void url;
};

/**
 * Update page title
 */
export const updateTitle = (companyName) => {
  // Native app: no document title.
  void companyName;
};

/**
 * Set cached settings manually (useful after update)
 */
export const setCachedSettings = (settings) => {
  if (settings) {
    cachedSettings = settings;
    try {
      localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
    } catch (e) {}

    updateFavicon(settings.favicon?.url);
    updateTitle(settings.companyName);
  }
};

/**
 * Clear cached settings (call after updating settings)
 */
export const clearCache = () => {
  cachedSettings = null;
  try {
    localStorage.removeItem(SETTINGS_KEY);
  } catch (e) {}
};

/**
 * Get cached settings
 */
export const getCachedSettings = () => {
  return cachedSettings;
};

/**
 * Get company name from business settings with fallback
 * @returns {string} Company name or default "Hello Parth Food"
 */
export const getCompanyName = () => {
  const settings = getCachedSettings();
  const name = settings?.companyName || "Hello Parth Food";
  return name === "Foodelo" ? "Hello Parth Food" : name;
};

/**
 * Get company name asynchronously (loads if not cached)
 * @returns {Promise<string>} Company name or default "Hello Parth Food"
 */
export const getCompanyNameAsync = async () => {
  try {
    const settings = await loadBusinessSettings();
    return settings?.companyName || "Hello Parth Food";
  } catch (error) {
    return "Hello Parth Food";
  }
};

