        {isValid ? <CheckCircle2 size={18} color="#10b981" /> : null}
      </View>
      {error ? (
        <View style={s.phoneErrorRow}>
          <AlertCircle size={11} strokeWidth={3} color="#ef4444" />
          <Text style={s.errorText}>{error}</Text>
        </View>
      ) : null}
    </View>
  );
};

