      {/* Share sheet */}
      <ShareSheetModal open={shareSheetOpen} onClose={() => setShareSheetOpen(false)} cardStyle={[styles.shareCard, SH, { backgroundColor: p.card, marginBottom: 20 + insets.bottom }]}>
