const compatibleResponseCache = new WeakMap();

const isCompatibleResponseCandidate = (value) => {
  if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
    return false;
  }

  if (typeof Blob !== 'undefined' && value instanceof Blob) {
    return false;
  }

  if (typeof ArrayBuffer !== 'undefined' && value instanceof ArrayBuffer) {
    return false;
  }

  if (typeof FormData !== 'undefined' && value instanceof FormData) {
    return false;
  }

  if (value instanceof Date) {
    return false;
  }

  return Array.isArray(value) || Object.prototype.toString.call(value) === '[object Object]';
};

const createCompatibleResponseView = (payload) => {
  if (!isCompatibleResponseCandidate(payload)) {
    return payload;
  }

  if (compatibleResponseCache.has(payload)) {
    return compatibleResponseCache.get(payload);
  }

  const proxy = new Proxy(payload, {
    get(target, prop, receiver) {
      if (prop === '__raw') {
        return target;
      }

      if (prop === 'data') {
        const nestedData = target?.data;
        if (nestedData === undefined || nestedData === target) {
          return receiver;
        }
        return createCompatibleResponseView(nestedData);
      }

      const directValue = Reflect.get(target, prop, receiver);
      if (directValue !== undefined) {
        return createCompatibleResponseView(directValue);
      }

      const nestedData = target?.data;
      if (nestedData && (Array.isArray(nestedData) || Object.prototype.toString.call(nestedData) === '[object Object]')) {
        if (prop in nestedData) {
          return createCompatibleResponseView(nestedData[prop]);
        }

        if (prop === 'results' && Array.isArray(nestedData)) {
          return createCompatibleResponseView(nestedData);
        }
      }

      return undefined;
    },
    has(target, prop) {
      if (prop in target) {
        return true;
      }

      const nestedData = target?.data;
      return Boolean(
        nestedData &&
        (Array.isArray(nestedData) || Object.prototype.toString.call(nestedData) === '[object Object]') &&
        prop in nestedData
      );
    },
  });

  compatibleResponseCache.set(payload, proxy);
  return proxy;
};

const DEDUPED_GET_TTL_MS = 2500;
// Admin reference lists (service areas, zones, vehicle types...) rarely change but ~11 admin pages each
// re-fetched them on every open. They are served from memory for a minute; ANY admin write clears them.
const REFERENCE_GET_TTL_MS = 60000;
const dedupedGetRequests = new Map();
const recentDedupedGetResponses = new Map();

const isReferenceGet = (url = '') => {
  const requestPath = String(url || '').split('?')[0];

  return /^\/admin\/(service-locations|zones|preferences|types\/vehicle-types\/list|types\/rental-packages|countries)$/.test(requestPath) ||
    /^\/countries$/.test(requestPath);
};

const isDedupedGet = (url = '') => {
  if (isReferenceGet(url)) {
    return true;
  }

  const requestPath = String(url || '').split('?')[0];

  return /^\/users\/me$/.test(requestPath) ||
    /^\/drivers\/me$/.test(requestPath) ||
    /^\/rides\/active\/me$/.test(requestPath) ||
    /^\/deliveries\/active\/me$/.test(requestPath) ||
    /^\/admin\/general-settings\/[^/]+$/.test(requestPath) ||
    /^\/common\/payment-gateway$/.test(requestPath) ||
    /^\/admin\/(countries|service-locations|notification-channels)$/.test(requestPath) ||
    /^\/(countries|common\/ride_modules)$/.test(requestPath) ||
    /^\/users\/(app-modules|bootstrap)$/.test(requestPath);
};

const getDedupedRequestKey = (url = '', config = {}) => {
  const params = config?.params ? JSON.stringify(config.params) : '';
  // Resolve the same auth token that the request interceptor will attach so
  // user-specific GETs never share cache entries across auth states.
  const auth = resolveAuthTokenForRequest({ ...config, url }) || '';
  return `${String(url || '')}|${params}|${auth}`;
};

const decodeBase64Url = (value) => {
  const normalized = String(value || '').replace(/-/g, '+').replace(/_/g, '/');
  const padding = (4 - (normalized.length % 4)) % 4;
  return normalized + '='.repeat(padding);
};

const getTokenPayload = (token) => {
  if (!token || typeof token !== 'string') {
    return null;
  }

  try {
    const payload = token.split('.')[1];

    if (!payload) {
      return null;
    }

    const decoded = JSON.parse(atob(decodeBase64Url(payload)));
    if (decoded && typeof decoded.exp === 'number') {
      const isExpired = Date.now() / 1000 >= decoded.exp;
      if (isExpired) {
        return null;
      }
    }
    return decoded;
  } catch {
    return null;
  }
};

const normalizeAuthRole = (role) => {
  const value = String(role || '').toLowerCase();
  if (value === 'super-admin') {
    return 'admin';
  }
  return value;
};

const DRIVER_PORTAL_ROLES = new Set([
  'driver',
  'owner',
  'bus_driver',
]);

const getSessionItem = (key) => {
  try {
    return sessionStorage.getItem(key);
  } catch {
    return null;
  }
};

const getStoredTokenByRole = (role) => {
  const normalizedRole = normalizeAuthRole(role);

  // For driver/owner roles we probe both sessionStorage AND localStorage so
  // that after a Flutter WebView hard-refresh (which wipes sessionStorage) we
  // can still find the persisted token in localStorage and avoid sending
  // unauthenticated requests that produce "Authorization token is required".
  const entries = (
    normalizedRole === 'driver' || normalizedRole === 'owner'
      ? [
          getSessionItem('driverToken'),
          getSessionItem('token'),
          localStorage.getItem('driverToken'),
          localStorage.getItem('token'),
        ]
      : normalizedRole === 'admin'
        ? [
            // Shared Food admin login stores `admin_accessToken`; taxi bridge uses `adminToken`.
            localStorage.getItem('admin_accessToken'),
            localStorage.getItem('adminToken'),
            localStorage.getItem('token'),
          ]
      : [
          localStorage.getItem(`${role}Token`),
          localStorage.getItem('token'),
        ]
  ).filter(Boolean);

  return entries.find((token) => {
    const tokenRole = normalizeAuthRole(getTokenPayload(token)?.role);

    if ((normalizedRole === 'driver' || normalizedRole === 'owner') && DRIVER_PORTAL_ROLES.has(tokenRole)) {
      return true;
    }

    return tokenRole === normalizedRole;
  }) || null;
};

const getRoleFromPathname = () => {
  if (typeof window === 'undefined') {
    return '';
  }

  const pathname = String(getAppRoutePath() || '').toLowerCase();

  if (pathname.includes('/admin')) {
    return 'admin';
  }

  // Owners currently authenticate with driver tokens (fleet-owner flow).
  if (pathname.includes('/taxi/owner')) {
    return 'driver';
  }

  if (pathname.includes('/taxi/driver') || pathname.includes('/driver')) {
    return 'driver';
  }

  if (pathname.includes('/taxi/user') || pathname.includes('/user')) {
    return 'user';
  }

  return '';
};

const resolveAuthTokenForRequest = (config = {}) => {
  const requestPath = String(config.url || '').split('?')[0];
  const existingAuthorization = config.headers?.Authorization || config.headers?.authorization;

  if (existingAuthorization) {
    return String(existingAuthorization).startsWith('Bearer ')
      ? String(existingAuthorization).slice(7)
      : String(existingAuthorization);
  }

  const chatRole = localStorage.getItem('chatRole');
  const normalizedChatRole = String(chatRole || '').toLowerCase();
  const userToken = getStoredTokenByRole('user');
  const driverToken = getStoredTokenByRole('driver');
  const ownerToken = getStoredTokenByRole('owner');
  const adminToken =
    getStoredTokenByRole('admin') ||
    localStorage.getItem('admin_accessToken') ||
    localStorage.getItem('adminToken');

  const isPublicUserRoute =
    /^\/users\/(bootstrap|app-modules|settings|goods-types|vehicle-types|register|signup|login|profile-image|auth\/send-otp|auth\/verify-otp)(\/|$)/.test(requestPath);
  const isPublicDriverRoute =
    /^\/drivers\/(register|login|auth\/send-otp|auth\/verify-otp|onboarding\/send-otp|onboarding\/verify-otp|onboarding\/personal|onboarding\/referral|onboarding\/vehicle|onboarding\/documents|onboarding\/complete|onboarding\/session\/|service-locations)(\/|$)/.test(requestPath);
  const isAdminRoute =
    /^\/admin(\/|$)/.test(requestPath) ||
    /^\/(countries|common\/ride_modules|types\/|on-boarding(?:-|\/|$)|roles\/|permissions\/)/.test(requestPath);
  const isDriverRoute = /^\/drivers?(\/|$)/.test(requestPath);
  const isUserRoute = /^\/(users|rides|deliveries|promos)(\/|$)/.test(requestPath);
  const isSupportRoute = /^\/support(\/|$)/.test(requestPath);
  const isChatRoute = /^\/chats?(\/|$)/.test(requestPath);
  const pathRole = getRoleFromPathname();

  if (isPublicUserRoute || isPublicDriverRoute) {
    return null;
  }

  if (isChatRoute) {
    if (normalizedChatRole === 'admin') {
      return adminToken;
    }
    if (normalizedChatRole === 'driver') {
      return driverToken || ownerToken;
    }
    if (normalizedChatRole === 'owner') {
      return ownerToken || driverToken;
    }
    if (normalizedChatRole === 'user') {
      return userToken;
    }
  }

  if (isAdminRoute) {
    return adminToken;
  }

  if (isSupportRoute) {
    if (pathRole === 'admin') {
      return adminToken;
    }
    if (pathRole === 'driver') {
      return driverToken || ownerToken;
    }
    return userToken;
  }

  if (isUserRoute) {
    return userToken;
  }

  if (isDriverRoute) {
    return driverToken || ownerToken;
  }

  return userToken || driverToken || ownerToken || adminToken || null;
};

const clearStaleAuthState = (role = '', staleToken = '') => {
  const normalizedRole = normalizeAuthRole(role);
  const currentGenericToken = localStorage.getItem('token');
  const currentSessionGenericToken = getSessionItem('token');
  const shouldClearGenericToken =
    !staleToken ||
    currentGenericToken === staleToken ||
    currentSessionGenericToken === staleToken ||
    normalizeAuthRole(getTokenPayload(currentGenericToken)?.role) === normalizedRole;

  if (shouldClearGenericToken) {
    localStorage.removeItem('token');
    try {
      sessionStorage.removeItem('token');
    } catch {}
  }

  if (!normalizedRole || normalizedRole === 'user') {
    if (!staleToken || localStorage.getItem('userToken') === staleToken) {
      localStorage.removeItem('userToken');
    }
    localStorage.removeItem('userInfo');
  }

  if (!normalizedRole || normalizedRole === 'driver' || normalizedRole === 'owner') {
    if (!staleToken || localStorage.getItem('driverToken') === staleToken) {
      localStorage.removeItem('driverToken');
    }
    try {
      if (!staleToken || getSessionItem('driverToken') === staleToken) {
        sessionStorage.removeItem('driverToken');
      }
      sessionStorage.removeItem('driverInfo');
      sessionStorage.removeItem('chatRole');
    } catch {}
    localStorage.removeItem('driverInfo');
  }

  if (!normalizedRole || normalizedRole === 'admin') {
    if (!staleToken || localStorage.getItem('adminToken') === staleToken) {
      localStorage.removeItem('adminToken');
    }
    if (!staleToken || localStorage.getItem('admin_accessToken') === staleToken) {
      localStorage.removeItem('admin_accessToken');
    }
    localStorage.removeItem('adminInfo');
    localStorage.removeItem('admin_user');
    localStorage.removeItem('admin_refreshToken');
    localStorage.removeItem('admin_authenticated');
  }

  localStorage.removeItem('chatRole');
};

const isStaleAuthMessage = (message = '') => {
  const normalizedMessage = String(message || '').trim().toLowerCase();
  return normalizedMessage === 'jwt expired' || normalizedMessage === 'invalid authorization token';
};

// Request Interceptor: Attach Auth Token automatically
api.interceptors.request.use(
  (config) => {
    const existingAuthorization = config.headers?.Authorization || config.headers?.authorization;

    if (existingAuthorization) {
      return config;
    }
    const token = resolveAuthTokenForRequest(config);

    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response Interceptor: Simplify responses and handle global errors
api.interceptors.response.use(
  (response) => {
    // Pro-Level: Many APIs return data in data.data or data.result, you can flatten it here
    return createCompatibleResponseView(response.data);
  },
  (error) => {
    if (error.response) {
      // Global error handling: e.g. deleted or inactive account logout
      const serverMessage = String(error.response.data?.message || '');
      const authHeader = error.config?.headers?.Authorization || error.config?.headers?.authorization || '';
      const token = String(authHeader).startsWith('Bearer ') ? String(authHeader).slice(7) : '';
      const tokenRole = normalizeAuthRole(getTokenPayload(token)?.role || '');

      const is401 = error.response.status === 401;
      const is403 = error.response.status === 403;
      const isStaleMessage = isStaleAuthMessage(serverMessage);
      const isDeactivatedOrDeleted =
        serverMessage === 'Authenticated account no longer exists' ||
        (tokenRole === 'user' && serverMessage === 'User account is not active');

      const shouldClearAuth =
        (is401 ||
        isStaleMessage ||
        (is403 && isDeactivatedOrDeleted)) &&
        Boolean(token);

      if (shouldClearAuth) {
        clearStaleAuthState(tokenRole, token);
        window.dispatchEvent(new CustomEvent('app:auth-stale', {
          detail: { role: tokenRole || null, message: serverMessage, token },
        }));
      }

      // `response` is kept on the rejected value too: ~40 screens read error.response.data.message, and without it
      // they all fell back to a generic "check your connection" text for every server answer.
      return Promise.reject({
        ...error.response.data,
        status: error.response.status,
        response: { status: error.response.status, data: error.response.data },
      });
    }

    return Promise.reject({ message: 'Network error or server down.' });
  }
);

const rawGet = api.get.bind(api);

const dedupedApiGet = (url, config = {}) => {
  if (!isDedupedGet(url)) {
    // Everything else: GETs in flight at the same moment share one request (nothing is kept afterwards).
    if (config?.signal || config?.responseType === 'blob' || config?.responseType === 'arraybuffer' || config?.dedupe === false) {
      return rawGet(url, config);
    }
    const liveKey = getDedupedRequestKey(url, config);
    const live = dedupedGetRequests.get(liveKey);
    if (live) {
      return live;
    }
    const liveRequest = rawGet(url, config).finally(() => {
      if (dedupedGetRequests.get(liveKey) === liveRequest) {
        dedupedGetRequests.delete(liveKey);
      }
    });
    dedupedGetRequests.set(liveKey, liveRequest);
    return liveRequest;
  }

  const key = getDedupedRequestKey(url, config);
  const now = Date.now();
  const cached = recentDedupedGetResponses.get(key);
  const ttl = isReferenceGet(url) ? REFERENCE_GET_TTL_MS : DEDUPED_GET_TTL_MS;

  if (cached && now - cached.timestamp < ttl) {
    return Promise.resolve(cached.data);
  }

  const pending = dedupedGetRequests.get(key);

  if (pending) {
    return pending;
  }

  const request = rawGet(url, config)
    .then((data) => {
      recentDedupedGetResponses.set(key, {
        data,
        timestamp: Date.now(),
      });
      return data;
    })
    .finally(() => {
      dedupedGetRequests.delete(key);
    });

  dedupedGetRequests.set(key, request);
  return request;
};

// Reads that only feed a badge / reminder start a moment later so they never queue in front of the open screen.
api.get = (url, config = {}) =>
  isBackgroundGet(url, config) ? runInBackground(() => dedupedApiGet(url, config)) : dedupedApiGet(url, config);

// Any write may change a reference list, so drop the cached ones (after success AND failure — a failed
// write can still have changed something server-side).
const clearReferenceCache = () => {
  Array.from(recentDedupedGetResponses.keys()).forEach((key) => {
    if (isReferenceGet(key.split('|')[0])) {
      recentDedupedGetResponses.delete(key);
    }
  });
};

['post', 'put', 'patch', 'delete'].forEach((method) => {
  const rawMethod = api[method].bind(api);
  api[method] = (...args) => {
    // A GET sent after a write must not join a read that started before it.
    dedupedGetRequests.clear();
    return rawMethod(...args).then(
      (response) => {
        clearReferenceCache();
        return response;
      },
      (error) => {
        clearReferenceCache();
        throw error;
      },
    );
  };
});

export default api;

// Web: modules/Taxi/shared/context/SettingsContext.jsx — the Taxi start-up settings (GET /users/bootstrap), cached in
// localStorage (appSettingsCache:v1) so the first Taxi screen has them at once, refreshed on resume / online / focus.
// Not reproduced (no DOM): document.title and the admin theme CSS variables on <html> (admin panel only).
import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import api from '../api/axiosInstance';
import { BACKEND_ORIGIN } from '../api/runtimeConfig';
import { preloadBannerImage } from '@/shared/utils/bannerImage';

const SETTINGS_CACHE_KEY = 'appSettingsCache:v1';

export const normalizeAssetUrl = (url = '') => {
  if (!url || typeof url !== 'string') return '';
  if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('data:')) {
    return url;
  }
  return `${BACKEND_ORIGIN}${url.startsWith('/') ? '' : '/'}${url}`;
};

const DEFAULT_SETTINGS_CONTEXT = {
  settings: {
    general: {
      app_name: 'Hello Parth Taxi',
      logo: '',
      favicon: '',
    },
    customization: {
      admin_theme_color: '',
      currency_symbol: '',
    },
    transportRide: {
      enable_bus_service: '0',
    },
    bidRide: {
      bidding_low_percentage: '10',
      bidding_high_percentage: '20',
      bidding_amount_increase_or_decrease: '10',
      user_bidding_low_percentage: '10',
      user_bidding_high_percentage: '20',
      user_bidding_amount_increase_or_decrease: '10',
      user_fare_increase_wait_minutes: '2',
    },
    paymentGateway: null,
    userHomeSettings: {},
    homeBanner: {},
  },
  modules: [],
  loading: true,
  hasBootstrapSettings: false,
  settingsFresh: false,
  refreshSettings: () => {},
};
const SettingsContext = createContext(DEFAULT_SETTINGS_CONTEXT);

const normalizeBooleanSetting = (value, fallback = '0') => {
  if (typeof value === 'boolean') {
    return value ? '1' : '0';
  }

  if (typeof value === 'number') {
    return value === 1 ? '1' : '0';
  }

  const normalized = String(value || '').trim().toLowerCase();
  if (!normalized) {
    return fallback;
  }

  if (['1', 'true', 'yes', 'on', 'enabled'].includes(normalized)) {
    return '1';
  }

  if (['0', 'false', 'no', 'off', 'disabled'].includes(normalized)) {
    return '0';
  }

  return fallback;
};

const normalizeTransportRideSettings = (settings = {}) => ({
  ...settings,
  enable_bus_service: normalizeBooleanSetting(settings?.enable_bus_service, '0'),
});

const buildSettingsState = (payload = {}) => ({
  general: {
    ...(payload?.general || {}),
    logo: normalizeAssetUrl(payload?.general?.logo),
    favicon: normalizeAssetUrl(payload?.general?.favicon),
  },
  customization: payload?.customization || {},
  transportRide: normalizeTransportRideSettings(payload?.transportRide || {}),
  bidRide: payload?.bidRide || DEFAULT_SETTINGS_CONTEXT.settings.bidRide,
  paymentGateway: payload?.paymentGateway || null,
  userHomeSettings: payload?.userHomeSettings || {},
  homeBanner: payload?.homeBanner || {},
});

const readCachedSettings = () => {
  try {
    const raw = localStorage.getItem(SETTINGS_CACHE_KEY);
    if (!raw) {
      return null;
    }

    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') {
      return null;
    }

    return buildSettingsState(parsed);
  } catch {
    return null;
  }
};

const writeCachedSettings = (settings) => {
  try {
    localStorage.setItem(SETTINGS_CACHE_KEY, JSON.stringify(settings));
  } catch {
    // Cache writes are best-effort only.
  }
};

const settingsFromBootstrap = (data = {}) =>
  buildSettingsState({
    general: data.settings?.general || {},
    customization: data.settings?.customization || {},
    transportRide: data.settings?.transportRide || {},
    bidRide: data.settings?.bidRide || DEFAULT_SETTINGS_CONTEXT.settings.bidRide,
    paymentGateway: data.settings?.paymentGateway || null,
    userHomeSettings: data.settings?.userHomeSettings || {},
    homeBanner: data.settings?.homeBanner || {},
  });

// When the start-up settings last arrived (from the provider or from the warm-up below). While they are recent, the
// Taxi home knows for sure whether a banner image is uploaded and does not have to wait for them again.
const FRESH_FOR_MS = 5 * 60 * 1000;
let bootstrapArrivedAt = 0;
const bootstrapIsFresh = () => bootstrapArrivedAt > 0 && Date.now() - bootstrapArrivedAt < FRESH_FOR_MS;

/**
 * Starts downloading the Taxi home banner ahead of time: the uploaded picture when there is one, otherwise the
 * default design's vehicle picture.
 */
const warmHomeBanner = (settings) => {
  const uploaded = normalizeAssetUrl(settings?.homeBanner?.taxiImageUrl);
  if (uploaded) {
    preloadBannerImage(uploaded);
    return;
  }
  import('../../modules/user/components/TaxiHeroBanner').then((mod) => mod.preloadHeroArt()).catch(() => {});
};

/**
 * Downloads the public start-up settings ahead of time (the login screen calls this while the person types their
 * number; Food calls it too) and stores them in the cache SettingsProvider reads when Taxi opens. Needs no login;
 * never throws.
 */
export const prefetchTaxiSettings = async () => {
  if (bootstrapIsFresh()) {
    warmHomeBanner(readCachedSettings());
    return;
  }
  try {
    // Warm-up read made from the OTHER app (Food): runs behind that screen's own requests.
    const response = await api.get('/users/bootstrap', { background: true });
    const fresh = settingsFromBootstrap(response?.data?.data || response?.data || {});
    writeCachedSettings(fresh);
    bootstrapArrivedAt = Date.now();
    warmHomeBanner(fresh);
  } catch {
    // purely an optimisation
    warmHomeBanner(readCachedSettings());
  }
};

export const SettingsProvider = ({ children }) => {
  const [cachedSettings] = useState(readCachedSettings);
  const [settings, setSettings] = useState(cachedSettings || DEFAULT_SETTINGS_CONTEXT.settings);
  // Cached settings already have something to show — no loading state just because a background refresh will run.
  const [loading, setLoading] = useState(!cachedSettings);
  const [hasBootstrapSettings, setHasBootstrapSettings] = useState(Boolean(cachedSettings));
  // True once there is an answer from the server (not just the saved copy): only then is it certain whether a home
  // banner image is uploaded. Stays true when the provider is mounted again within a few minutes.
  const [settingsFresh, setSettingsFresh] = useState(bootstrapIsFresh);
  const [modules, setModules] = useState([]);

  const lastFetchAtRef = useRef(0);
  const mountedRef = useRef(true);

  const fetchSettings = async () => {
    lastFetchAtRef.current = Date.now();
    try {
      const response = await api.get('/users/bootstrap');
      const data = response?.data?.data || response?.data || {};

      const nextSettings = settingsFromBootstrap(data);
      writeCachedSettings(nextSettings);
      bootstrapArrivedAt = Date.now();
      if (!mountedRef.current) return;

      setSettings(nextSettings);
      setModules(data.modules || []);
      setHasBootstrapSettings(true);
    } catch (err) {
      console.error('[SettingsContext] Failed to fetch bootstrap settings:', err);
    } finally {
      if (mountedRef.current) {
        setLoading(false);
        // Also after a failure: the answer is not coming, so show what is saved (or the default banner).
        setSettingsFresh(true);
      }
    }
  };

  useEffect(() => {
    mountedRef.current = true;
    fetchSettings();
    return () => {
      mountedRef.current = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    // Skip resume-refreshes that land within a few seconds of the last fetch.
    const MIN_REFRESH_GAP_MS = 4000;
    const refreshOnResume = () => {
      if (Date.now() - lastFetchAtRef.current < MIN_REFRESH_GAP_MS) return;
      fetchSettings();
    };

    window.addEventListener('pageshow', refreshOnResume);
    window.addEventListener('online', refreshOnResume);
    window.addEventListener('focus', refreshOnResume);

    return () => {
      window.removeEventListener('pageshow', refreshOnResume);
      window.removeEventListener('online', refreshOnResume);
      window.removeEventListener('focus', refreshOnResume);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const refreshSettings = () => fetchSettings();

  return (
    <SettingsContext.Provider value={{ settings, modules, loading, hasBootstrapSettings, settingsFresh, refreshSettings }}>
      {children}
    </SettingsContext.Provider>
  );
};

export const useSettings = () => {
  return useContext(SettingsContext);
};

import { getDatabase, onValue as onRealtimeValue, ref } from 'firebase/database';
import { ensureFirebaseInitialized } from '@food/firebase';
const FIREBASE_DATABASE_URL = String(globalThis.__ENV__.VITE_FIREBASE_DATABASE_URL || '').trim().replace(/\/$/, '');

export const HAS_FIREBASE_RIDE_DB = FIREBASE_DATABASE_URL.length > 0;
let firebaseRideAccessDenied = false;

const rideUrl = (rideId) => `${FIREBASE_DATABASE_URL}/taxiRides/${encodeURIComponent(String(rideId))}.json`;


const toCoordsArray = (value, fallback = null) => {
  if (Array.isArray(value) && value.length >= 2) {
    const [lng, lat] = value;
    if (Number.isFinite(Number(lat)) && Number.isFinite(Number(lng))) {
      return [Number(lng), Number(lat)];
    }
  }

  const lat = Number(value?.lat ?? value?.latitude);
  const lng = Number(value?.lng ?? value?.longitude ?? value?.lon);

  if (Number.isFinite(lat) && Number.isFinite(lng)) {
    return [lng, lat];
  }

  return fallback;
};

export const pointSnapshot = (value, fallbackAddress = '') => {
  const coordinates = toCoordsArray(value, null);

  if (!coordinates) {
    return null;
  }

  return {
    coordinates,
    lng: coordinates[0],
    lat: coordinates[1],
    address: String(value?.address || fallbackAddress || ''),
    updatedAt: new Date().toISOString(),
  };
};

const mergeByPath = (target, path, data) => {
  if (!path || path === '/') {
    return data;
  }

  const segments = String(path).split('/').filter(Boolean);
  const next = { ...(target || {}) };
  let cursor = next;

  for (let index = 0; index < segments.length - 1; index += 1) {
    const key = segments[index];
    cursor[key] = typeof cursor[key] === 'object' && cursor[key] !== null ? { ...cursor[key] } : {};
    cursor = cursor[key];
  }

  cursor[segments[segments.length - 1]] = data;
  return next;
};

export const createRideRealtimeSnapshot = ({
  rideId,
  pickup,
  drop,
  fare,
  status = 'searching',
  userId = '',
  driverId = '',
  driver = null,
}) => ({
  rideId: String(rideId),
  pickup: pointSnapshot(pickup),
  drop: pointSnapshot(drop),
  fare: Number(fare || 0),
  status,
  userId: userId ? String(userId) : '',
  driverId: driverId ? String(driverId) : '',
  driver: driver || null,
  driverLocation: null,
  updatedAt: new Date().toISOString(),
});

const writeJson = async (rideId, method, payload) => {
  if (!HAS_FIREBASE_RIDE_DB || !rideId || firebaseRideAccessDenied) {
    return null;
  }

  const response = await fetch(rideUrl(rideId), {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  if (response.status === 401 || response.status === 403) {
    firebaseRideAccessDenied = true;
    return null;
  }

  if (!response.ok) {
    throw new Error(`Firebase ride sync failed (${response.status})`);
  }

  return response.json().catch(() => null);
};

export const seedRideRealtime = (payload) => writeJson(payload.rideId, 'PUT', createRideRealtimeSnapshot(payload));

export const patchRideRealtime = (rideId, payload) =>
  writeJson(rideId, 'PATCH', {
    ...payload,
    updatedAt: new Date().toISOString(),
  });

export const pushDriverLocationRealtime = (rideId, location, extra = {}) =>
  patchRideRealtime(rideId, {
    driverLocation: {
      ...pointSnapshot(location),
      heading: Number.isFinite(Number(extra.heading)) ? Number(extra.heading) : null,
      speed: Number.isFinite(Number(extra.speed)) ? Number(extra.speed) : null,
      updatedAt: new Date().toISOString(),
    },
  });

// The web read this path as a Firebase REST event stream (EventSource), which React Native does not have. The app
// listens to the same path (taxiRides/<rideId>) with the Firebase SDK's onValue, which delivers the full current state.
export const subscribeRideRealtime = (rideId, onValue, onError) => {
  if (!HAS_FIREBASE_RIDE_DB || !rideId || firebaseRideAccessDenied) {
    return () => {};
  }

  const firebaseApp = ensureFirebaseInitialized({ enableAuth: false, enableRealtimeDb: true });
  const db = firebaseApp ? getDatabase(firebaseApp) : null;
  if (!db) return () => {};

  const unsubscribe = onRealtimeValue(
    ref(db, 'taxiRides/' + String(rideId)),
    (snapshot) => {
      try {
        onValue(snapshot.val());
      } catch (error) {
        onError?.(error);
      }
    },
    (error) => {
      firebaseRideAccessDenied = true;
      onError?.(error);
    },
  );

  return () => {
    unsubscribe();
  };
};

