 * Used by the login BACK button so we never re-enter the redirect loop.
 */
const AUTH_GATED_ROUTE_SEGMENTS = [
  '/activity',
  '/profile',
  '/wallet',
  '/support',
  '/ride/searching',
  '/ride/tracking',
  '/ride/complete',
  '/ride/chat',
  '/ride/detail',
  '/parcel/type',
  '/parcel/details',
  '/parcel/contacts',
  '/parcel/searching',
  '/parcel/tracking',
  '/parcel/detail',
  '/intercity/confirm',
  '/food/user/cart',
  '/food/user/checkout',
  '/food/user/orders',
  '/food/user/profile',
  '/food/user/wallet',
  '/food/user/address',
]

const isAuthGatedRoute = (route = '') => {
  const value = String(route || '').split('?')[0]
  if (!value) return false
  return AUTH_GATED_ROUTE_SEGMENTS.some((seg) => value.includes(seg))
}

const toPublicModuleHome = (route = '') => {
  const value = String(route || '')
  if (value.startsWith('/taxi/') || value === 'taxi') return '/taxi/user'
  if (value.startsWith('/food/') || value === 'food') return '/food/user'
  return ''
}

/**
 * Post-login destination for the consumer (/login) auth flow only.
 * Must never send users to admin/restaurant/delivery panels — those have
 * their own login screens.
 */
export function resolvePostLoginRoute() {
  return CONSUMER_POST_LOGIN_HOME
}

/**
 * Mark explicit guest browsing for Food when no login token exists.
 * Matches "Skip for now" semantics so super-app tab switches open Food home.
 */
export function ensureFoodGuestSession() {
  if (typeof localStorage === 'undefined') return
  const token = localStorage.getItem('user_accessToken')
  const authStatus = localStorage.getItem('user_authenticated')
  if (!token && authStatus === null) {
    localStorage.setItem('user_authenticated', 'false')
  }
}

/**
 * Back from /login while still logged out.
 * Guests always return to Food — Taxi routes are login-only and would loop.
 */
export function resolveLoginBackRoute(locationStateFrom) {
  const fromPath = String(locationStateFrom || '').trim().split('?')[0]
  const storedReturn = peekLoginReturnTo()
  const foodToken = typeof localStorage !== 'undefined'
    ? String(localStorage.getItem('user_accessToken') || '').trim()
    : ''
  const taxiToken = typeof localStorage !== 'undefined'
    ? String(localStorage.getItem('userToken') || '').trim()
    : ''
  const isLoggedIn = Boolean(foodToken || taxiToken)

  const hint = fromPath || storedReturn

  if (isLoggedIn && (hint.startsWith('/taxi/') || hint === 'taxi' || String(hint).includes('/taxi/'))) {
    return '/taxi/user'
  }

  // Default / guest: Food browse
  return '/food/user'
}

const DEFAULT_MAX_WIDTH = 2048
const DEFAULT_MAX_HEIGHT = 2048
const DEFAULT_QUALITY = 0.88
const DEFAULT_MAX_BYTES = 4.5 * 1024 * 1024

const PROFILE_PRESET = {
  maxWidth: 1024,
  maxHeight: 1024,
  maxBytes: 2 * 1024 * 1024,
  quality: 0.88,
}

export async function compressImageForUpload(file, options = {}) {
  // In the app a picked photo is a { uri, name, type } descriptor from src/lib/media.js pickImage(), which the system
  // picker already re-encodes (quality 0.8) - there is no canvas to re-encode it again. Browser Blobs never occur here.
  // The size options are accepted so the callers stay as on the web.
  void options
  return file
}

export async function compressImagesForUpload(files = [], options = {}) {
  const normalized = Array.from(files || []).filter(Boolean)
  return Promise.all(normalized.map((file) => compressImageForUpload(file, options)))
}

export async function prepareUploadFile(file, options = {}) {
  if (!file) return file

  const preset =
    options.preset === "profile"
      ? PROFILE_PRESET
      : {}

  return compressImageForUpload(file, { ...preset, ...options })
}

export async function prepareUploadFiles(files = [], options = {}) {
  const normalized = Array.from(files || []).filter(Boolean)
  return Promise.all(normalized.map((file) => prepareUploadFile(file, options)))
}

export async function appendCompressedImageToFormData(formData, fieldName, file, options = {}) {
  if (!file || !formData) return formData
  const prepared = await prepareUploadFile(file, options)
  formData.append(fieldName, prepared)
  return formData
}

export async function appendCompressedImagesToFormData(formData, fieldName, files = [], options = {}) {
  if (!formData) return formData
  const preparedFiles = await prepareUploadFiles(files, options)
  preparedFiles.forEach((file) => formData.append(fieldName, file))
  return formData
}

